quests[25808] = { id = 25808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das Ding an?", description = "<Der Gnomcorder summt energiegeladen. Man hört Leutnant Paulson am anderen Ende.>\n\nDämlicher Gnomschrott... Ist da IRGENDWER? {name}, seid Ihr da?\n\nVielleicht ist <er/sie> tot.\n\nFalls Ihr mich hören könnt - wir haben gerade die Nachricht erhalten, dass eine Meisterassassine der Horde sich in den Minen befindet und die anderen Auftragsmörder befehligt. Findet sie, tötet sie und meldet Euch bei mir.\n\nPaulson Ende.", sourceObjective = "Tötet Meisterassassine Kel'istra.", completion = "Gut gemacht, {name}! Eure Arbeit in den Minen war die eines Profis. Wie wäre es, wenn Ihr mir jetzt meine Brille zurückgebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25809] = { id = 25809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst niemanden zurück!", description = "Hordenmonster!\n\n<Korporal Wocard spuckt aus.>\n\nSchaut Euch das hier an! Sie haben Unschuldige getötet! Zivilisten!\n\nHört zu, {name}, Ihr müsst uns helfen. Geht in die Ausufernden Tiefen und sucht nach überlebenden Minenarbeitern. Wenn einige überlebt haben, werden sie wohl vollkommen verängstigt sein! Sucht in allen Nischen und Winkeln der Mine. Vielleicht sogar in den Minenwagen! Es gibt ganz bestimmt Überlebende, die sich irgendwo versteckt haben.", sourceObjective = "Rettet 8 Verängstigte Minenarbeiter.", completion = "Dem Licht sei Dank! Ihr seid wahrlich ein rechtschaffendes Instrument der Macht! Die Allianz kann sich glücklich schätzen, Euch zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25810] = { id = 25810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brutstätte muss brennen", description = "{name}! Choluna hat die Wahrheit gesprochen: Die Göttin ist zurückgekehrt! Ein Wunder ist geschehen.\n\nIhr habt zwar den Zwielichtdrachen Sethria töten können, wir haben jedoch noch nicht alle Eier ausfindig gemacht, die die Harpyien ihr gebracht hatten. Thisalee und ich haben ihnen nachgespürt und sind dabei auf eine große Brutstätte in den Feuerlanden gestoßen. Sie ist nicht von dieser Welt, also kann Aviana Euch nicht begleiten.\n\nFliegt nach Süden und tretet durch das Flammentor in der Mitte des Tals. Farden Klauenwürger ist vorausgesandt worden und wird im Inneren auf Euch warten.", sourceObjective = "Reist durch das Flammentor in der Mitte der Flammenschneise auf dem Hyjal. Sprecht mit Farden Klauenwürger, sobald Ihr hindurchgegangen seid.", completion = "Also ist es wahr. Aviana ist mit Euch als Herold zurückgekehrt.\n\nEs gibt hier viel zu tun. Wir sind tief im Herzen der Feuerlande. Sethria hat gestohlene Eier vom Hyjal hierher geschmuggelt, um ihre eigenen abstoßenden Kreaturen zu züchten: Raubvögel, die für den Krieg ausgebildet sind.\n\nIch hoffe, dass Ihr bereit seid, zurückzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25811] = { id = 25811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stilllegung", description = "Um diese Mine stillzulegen, müsst Ihr die tragenden Pfeiler in die Luft jagen. Ich kann Euch den benötigten Sprengstoff zur Verfügung stellen, aber Ihr müsst Euch an den Auftragsmördern von Krom'gar vorbeischleichen, um alle Träger zu erreichen.\n\nDie gute Nachricht - wenn man das so nennen kann - ist, dass wir die tragenden Pfeiler immer mit einem großen X markiert haben. Schaut nach diesen Markierungen und befestigt das Dynamit in ihrer Nähe. Sobald ihr das Dynamit angebracht habt, kommt wieder hier hoch und ich werde die Sprengung auslösen.\n\nKabumm!", sourceObjective = "Verankert jeweils ein Dynamitbündel am ersten, zweiten, dritten und vierten Träger.", completion = "Wird schon schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25812] = { id = 25812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit dem Gefreiten Pollard in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[25813] = { id = 25813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25814] = { id = 25814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25815] = { id = 25815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dritte Flotte", description = "Ich war einst Erster Maat auf der 'Herrin der Meere', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs geritten wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Bringt mir meinen Met, {class}. Er ist unten im Keller des Gasthauses. Auch wenn ich ihn so weit von mir entfernt verstaut habe, ich komme doch nicht ohne aus.", sourceObjective = "Erhaltet Fitzsimmons' Met aus dem Keller des Gasthauses im Hafen von Menethil.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[25816] = { id = 25816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Umherwandeln verdammt", description = "<Gestärkt fährt Fitzsimmons mit seiner Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden untergegangen ist. Auf einem unserer Schiffe war ein großer und furchtbarer Schatz versteckt und seine gespenstische Macht hält die Seelen meiner Brüder gefangen in den verrottenden Schiffsrümpfen.\n\nIch werde Tag und Nacht von ihnen verfolgt. Der Erste Maat Snellig ruft mich! Er sollte eigentlich tot sein! Bitte, {name} sucht ihn bei den Schiffswracks und... sagt ihm einfach, er soll mich in Ruhe lassen!", sourceObjective = "Sprecht mit dem Geist des Ersten Maats Snellig.", completion = "Fitzsimmons hat Euch geschickt, nicht wahr? Es ist so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[25817] = { id = 25817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchte Crew", description = "Die Seeleute der Dritten Flotte sind durch einen Fluch für immer dazu verdammt, an diesen Ufern voller Qualen entlangzuwandeln. Fitzsimmons Seelenqual hängt mit uns zusammen - solange wir leiden, kann auch er nicht ruhen.\n\nIhr müsst das Leiden der Geister meiner Mannschaftskameraden beenden. Löscht ihre Geister auf dieser Ebene aus und kehrt zu mir zurück.", sourceObjective = "Tötet 5 verfluchte Seemänner und 5 verfluchte Marinesoldaten in der Verlorenen Flotte.", completion = "Die gequälten Schreie sind erstickt worden... doch die Ursache des Fluchs noch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25818] = { id = 25818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen des Fluchs", description = "Um den Fluch zu brechen, muss abgerechnet werden. Kapitän Halyndor hat uns alle dazu verdammt, ein verbotenes Artefakt zu begehren, das Auge von Paleth. Sein Geist will es noch immer und wacht über die Schließtruhe seines alten Schiffes, der 'Kühnheit'.\n\nVernichtet die Seele dessen, der uns einst so verfluchte, {class}. Besiegt den Kapitän, nehmt seinen Schlüssel und bringt das Auge von Paleth weit weg von diesem Ort.", sourceObjective = "Besorgt den Geldkassettenschlüssel der 'Kühnheit' von Kapitän Halyndor.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25819] = { id = 25819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies muss das schändliche Auge von Paleth sein, das die Seelen dieser Seefahrer verdammt hat.\n\nSolch eine Verderbnis muss ausgemerzt werden. Vielleicht kann Euch ein Priester im Hafen von Menethil helfen.", sourceObjective = "Bringt das verfluchte Auge von Paleth zu Glorin Stahlbraue im Hafen von Menethil im Sumpfland.", progress = "Wie kann ich Euch helfen, Junge?", completion = "Das Auge von Paleth? Ihr sagt, Fitzsimmons hat Euch geschickt?\n\nBeim Lichte... nicht schon wieder. Fitzsimmons ist tot, Mädchen. Ihr seid auch nicht der erste, der so zu mir kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25820] = { id = 25820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Mein Sohn Gimlok ist das Licht meines Lebens. Mein Herz geht auf, wenn ich ihn mit den anderen Kindern spielen sehe.\n\nTrotzdem mache ich mir Sorgen. Nur wenige Meter entfernt, in der Bucht, gibt es Haie. Was, wenn das Wasser so tief ist, dass einer hierher schwimmt...\n\nDer Gedanke ist unerträglich! Ihr habt sicher schon Schlimmeres bewältigt als wir Stadtbewohner, {race}. Würdet Ihr diese schrecklichen Haie für mich beseitigen? Wenigstens ein paar?", sourceObjective = "Tötet 10 Hafenschredderflossen.", completion = "Wie wundervoll, dass Ihr so etwas für eine verheiratete Frau wie mich getan habt. Ihr seid zu freundlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25821] = { id = 25821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Auftrag", description = "Ihr habt hier unten Bemerkenswertes geleistet, {name}. Truppenkommandant Valen ist das nicht entgangen. Er möchte Euch sofort sprechen. Er hat Euch für eine besondere Mission ausgewählt - eine, mit der wir die Übergriffe der Horde im Steinkrallengebirge hoffentlich endgültig stoppen werden.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Schon bei unserer ersten Begegnung wusste ich, dass Ihr eine besondere Schneeflocke seid, {name}. So besonders, dass ich niemandem außer Euch diese Aufgabe anvertrauen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25822] = { id = 25822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegswerkzeug", description = "Ich muss Euch noch einmal einer Gefahr aussetzen, {name}. Im Osten gibt es eine von der Horde erbeutete Ausgrabungsstelle, die reich an Mineralien ist. Kisten mit unseren Waffen befinden sich dort. Sie sind überall verstreut. Die Horde ist erst vor kurzem dort eingefallen. Es ist unwahrscheinlich, dass sie bereits all unsere Ausrüstung gefunden haben.\n\nGeht dorthin und besorgt unseren Grimmtotemfreunden ein paar Waffen!", sourceObjective = "Sammelt 10 Waffenkisten der Allianz.", progress = "Habt Ihr das Kriegswerkzeug gefunden?", completion = "Das sollte reichen, um hundert Grimmtotem auszurüsten! Jetzt müssen wir die Waffen ihrem Häuptling übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25823] = { id = 25823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unerbittliche Horde", description = "Es ist zwar äußerst wichtig, dass Ihr die Waffenkisten unverzüglich sichert, aber wir müssen die Grabstätte im Osten auch von der Horde säubern. Wir müssen vollen Zugang zur Ausgrabungsstätte erhalten, sonst können wir keine Nachschublinie für die Grimmtotemverbündeten schaffen.\n\nTötet alle Angehörigen der Horde, denen Ihr an der Grabstätte begegnet, {name}. Für den Ruhm der Allianz!", sourceObjective = "Tötet 12 Angehörige der Horde an der Grabstätte.", completion = "Ich werde der Infanterie befehlen, nachzurücken und die Zurückgebliebenen zu beseitigen. Hätten wir doch zehntausend wie Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25824] = { id = 25824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Soldat stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gefreiter Pollard und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[25825] = { id = 25825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Fizzel auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Was ist das? Ist das Öl?!", completion = "Es ist Öl! Ihr seid ja wirklich von unschätzbarem Wert, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25826] = { id = 25826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Pozzik auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Hallo noch mal. Ist das Öl?!", completion = "Es ist Öl! Ihr seid wirklich richtig gut, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25830] = { id = 25830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte lebende Wissenshüter", description = "Ihr habt die Ahnen erweckt, {name}, aber Aessina, der Geist der Wildnis, schweigt noch immer. Mit ihrer Hilfe können wir diesen Kampf zu unseren Gunsten wenden und den Schaden, den der Schattenhammer angerichtet hat, rückgängig machen.\n\nEs mag jemanden geben, der uns dabei helfen kann. Der älteste der Bäume, Nordu, stand seit Tausenden von Jahren in der Mitte dessen, was heute die Flammenschneise ist. Seine Weisheit ist so alt wie dieser Berg. Wenn dieser alte Baum noch am Leben ist, kann er uns vielleicht dabei helfen, Aessina zu erwecken. Sucht nach ihm!", sourceObjective = "Findet Nordu, das Urtum der Lehren, in der Flammenschneise auf dem Hyjal.", completion = "Ich… bin noch nicht… entschwunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25832] = { id = 25832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Aviana", description = "{name}, Ihr habt hier alles getan, was Ihr tun könnt. Die ganze Höhle wird bald in sich zusammenbrechen!\n\nIch treibe die letzten schwingenbewehrten Hengste zusammen und stelle sicher, dass das Flammentor hinter mir versiegelt wird.\n\nIhr solltet losgehen und Aviana berichten, dass diese abscheuliche Brutstätte der Vergangenheit angehört!", sourceObjective = "Kehrt zu Aviana am Schrein von Aviana auf dem Hyjal zurück.", completion = "<Avianas Gesicht ist wie versteinert, als Ihr ihr erzählt, was in der Brutstätte passiert ist.>\n\nSie haben meine Eier gestohlen, {class}. Sie haben sie an diesen widerlichen Ort gebracht. Sie verderbt.\n\nMeine Kinder gestohlen, gequält, in einem Flammenmeer getötet... Ja, wir werden den Schattenhammer dafür bezahlen lassen.\n\nAber ich muss zugeben, dass ein Teil von mir sich einfach in die Lüfte erheben und diese ganze... Welt... in Flammen sehen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25834] = { id = 25834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellvertreterkrieg", description = "Hört Ihr sie dort unten kämpfen, {name}? Anscheinend haben sich die Tauren der Grimmtotem mit der Horde überworfen. Ich weiß nicht, wie das geschehen ist, aber wir könnten es zu unserem Vorteil nutzen.\n\nIch werde ein Treffen mit dem Botschafter der Grimmtotem arrangieren. Ich möchte, dass Ihr eine Friedensgabe zusammenstellt.\n\n<Truppenkommandant Valen zeigt auf Kräcka.>\n\nRedet mit \"Kräcka\", {name}. Er weiß bereits, was zu tun ist.", sourceObjective = "Sprecht mit \"Kräcka\" Aschebäscha im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Man nennt mich \"Kräcka\", Junge: den besten Koch von Azeroth. Der Kommandant hat mir schon gesagt, was los ist. Wir müssen ein erstklassiges Taurenmenü zusammenstellen, damit wir eine Audienz beim Häuptling der Grimmtotem bekommen.\n\nBesorgt mir die Zutaten, dann koche ich etwas, dem kein Tauren widerstehen kann. Noch nicht mal ein grimmiger Tauren, oder was immer die auch sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25835] = { id = 25835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwindposten befreien", description = "Es ist an der Zeit, dass Ihr geht. Wie schnell die Küken aus dem Nest fallen - oder so ähnlich.\n\nWie dem auch sei, Ihr habt hier gute Arbeit geleistet, aber Quentin und die Nachtelfen haben einen Hilferuf ausgestoßen und benötigen dringend Unterstützung mit den Grimmtotem in Freiwindposten nordwestlich von hier.\n\nWenn Ihr mich fragt, da ist alle Hoffnung verloren, aber wer weiß ... vielleicht können sie es mit Eurer Hilfe wirklich schaffen?", sourceObjective = "Sprecht mit Quentin in Freiwindposten in Tausend Nadeln.", completion = "Ich bin froh, dass Fizzel Euch endlich hergeschickt hat. Wir helfen den Tauren dabei, Freiwindposten zurückzuerobern und die Grimmtotem zu verdrängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25836] = { id = 25836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwindposten befreien", description = "Es sieht so aus, als sei es an der Zeit, dass sich unsere Wege trennen - zumindest vorübergehend. Nordwestlich von hier benötigen die Tauren in Freiwindposten dringend Hilfe, um den Grimmtotemklan zurückzudrängen.\n\nDa Ihr hier so großartig helfen konntet, gehe ich davon aus, dass Ihr auch dort äußerst schnell als <Held/Heldin> gefeiert sein werdet!", sourceObjective = "Sprecht mit Thalia Bernhaut in Freiwindposten in Tausend Nadeln.", completion = "Ich fühle mich geehrt, dass Ihr zu Hilfe gekommen seid, {class}. Es war sehr freundlich von Pozzik, Euch zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25837] = { id = 25837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Dinner", description = "Für eine ordentliche Friedensgabe brauche ich folgende Zutaten:\n\nEier eines Kalimdoradlers. Ihr findet sie in den Nestern der Kalimdoradler. Sucht in dem Wald im Westen danach. Widderkeulen! Und zwar die Keulen des Steinkrallenwidders.\n\nDie letzte Zutat ist zwar schwer zu bekommen, aber wir brauchen sie für unser Widderlett. Reist nach Südwesten zur Steinschlagklamm und macht die Koboldhöhlen ausfindig. Tötet die Kobolde und stehlt ihren besonderen Käse.\n\nBringt alle Zutaten zu mir, dann werde ich ein Meisterwerk kochen!", sourceObjective = "Sammelt 6 Eier von Kalimdoradlern, 8 Widderkeulen und 10 Stücke Steinschlagkäse.", progress = "Das Widderlett macht sich nicht von allein!", completion = "Bleibt zurück, {name}, gleich gibt's 'ne Geschmacksexplosion und ich will nicht, dass Ihr verletzt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25838] = { id = 25838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe aus Stahlrosts Depot", description = "Dank Eurer Hilfe sind wir näher an die Zuflucht der Frostmähnen herangerückt. Unsere Streitkräfte werden bald in Position gehen und die Reserve der Frostmähnentrolle angreifen. Dann ist ihr Dorf ungeschützt.\n\nDas ist ein Fall für das Geheimteam Gnomeregan. Seine Techniker haben eine Möglichkeit gefunden, Kämpfer hinter die feindliche Linien zu bringen, ohne dass die Frostmähnen das bemerken. Begebt Euch zu Stahlrosts Depot nordöstlich der Stadt und sprecht mit Delber Kurbeldreh. Er wird Euch mehr darüber berichten.", sourceObjective = "Sprecht mit Delber Kurbeldreh in Stahlrosts Depot.", completion = "Ah, Ihr müsst der {class} sein, den Hauptmann Tharran schicken wollte. Ich habe einen Großteil des Geheimteams bereits mit einem Entfalt-O-Tron in Position nahe an die Zuflucht der Frostmähnen gebracht. Sie warten nur noch auf Euer Eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25839] = { id = 25839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ultrasichere Personalabschussgerät!", description = "Der Kataklysmus hat unsere Feinde näher gebracht, deshalb hat mich der Chef des Geheimdienstes von Gnomeregan gebeten, ein Gerät zu konstruieren, mit dem man Personal rasch und leise in jeden Teil Dun Moroghs transportieren kann.\n\nTataa, das ultrasichere Personalabschussgerät!\n\nMit nur einem Schuss Elektrizität und dank des SPE-Fallschirmsystems, äh, sehr späte Entfaltung für Laien, bringt Euch dieses Baby direkt zur Front. Steigt ein und bereitet Euch auf den Flug vor! Slamp Wackelrad erwartet Euch in der Landezone.", sourceObjective = "Fliegt mit dem ultrasicheren Personalabschussgerät zur Zuflucht der Frostmähnen.", completion = "Keine Sorge, das Gefühl, einen Stromschlag erhalten zu haben, vergeht nach ein paar Minuten. Es gibt wirklich schlimmere Fortbewegungsmittel. An dem Fallschirmsystem muss jedoch noch gearbeitet werden. Sehr späte Entfaltung ist ernst gemeint. Manchmal zu spät. Na ja, wir haben eine Mission zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25840] = { id = 25840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert den Widerstand", description = "Der Häuptling der Frostmähnen starb beim ersten Angriff der Troggs. Seitdem werden sie von einem sehr respektierten Krieger angeführt. Battok der Berserker war derjenige, der den Rückzug der Frostmähnen organisierte, das neue Dorf errichten ließ und die Angriffe gegen Kharanos und die Gebirgsjäger führte.\n\nWenn wir Battok beseitigen, sollte Chaos unter den Frostmähnen ausbrechen. Dann können sich die Gebirgsjäger um die Überlebenden kümmern. Battok hält sich östlich von hier im Dorf auf.", sourceObjective = "Tötet Battok den Berserker und 5 Krieger der Frostmähnen in der Zuflucht der Frostmähnen.", completion = "Sehr gute Arbeit, {name}. Ich gebe Hauptmann Tharran das Signal, dass Battok tot ist. Das sollte das Ende der Frostmähnenbedrohung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25841] = { id = 25841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff von oben", description = "Delbers Techniker haben Tag und Nacht gearbeitet, um uns bei den Vorbereitungen auf den Angriff zu helfen. Seine Leute haben nicht nur das Personalabschussgerät konstruiert und eingestellt, sondern auch das geheime Fliegergeschwader für den Angriff auf die Zuflucht der Frostmähnen vorbereitet. Sie warten auf das Signal zum Beginn ihrer Angriffe.\n\nNehmt dieses Leuchtfeuer und zündet es nahe der Gebäudegruppe am Nordrand des Dorfs und neben den Gebäuden am Südrand des Dorfs. Die Flugmaschinen werden an beiden Stellen zuschlagen.", sourceObjective = "Benutzt das Signalleuchtfeuer, um Luftangriffe am nördlichen und südlichen Rand der Zuflucht der Frostmähnen anzufordern.", completion = "Ihr und die Luftstaffel habt Euch vorbildlich verhalten. Die Frostmähnen werden jetzt sicherlich nicht mehr hier bleiben. Wir müssen nur noch die Überlebenden beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25842] = { id = 25842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuergefecht", description = "Es ist… zu spät für mich. Bis auf den Kern ist alles verbrannt. Ich habe Äonen erlebt… und doch scheint mein Ende so plötzlich zu kommen.\n\nAus altem kann neues Leben entstehen. Ich habe immer noch meine Weisheit, die ich weitergeben kann. Bitte… Lasst nicht zu, dass sie mich wegbringen, bevor meine Arbeit getan ist.\n\nHaltet meine Peiniger zurück... nur noch eine Weile, {class}.\n\nGebt mir ein paar Minuten und ich werde es mit tausenden Jahren vergelten.", sourceObjective = "Tötet 5 feurige Peiniger, um sie von Nordu fernzuhalten.", progress = "Seid Ihr da, {class}? Mein Augenlicht hat mich verlassen… Ich höre Kämpfe…", completion = "Danke, {race}.\n\nIch bin jetzt bereit.\n\nAlles, was ich bin, und alles, was dieser Wald je war… gehört jetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25843] = { id = 25843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Rache", description = "Der Berg erblüht wieder! Wenn wir schnell handeln, können wir unseren Vorteil ausnutzen.\n\nUnser alter Freund Tortolla, der Schildkrötenahn, ist bereits auf dem Weg. In seinem eigenen Tempo natürlich…\n\nFindet Tortolla östlich von hier, am Kopf des Pfades in die Verbrannte Ebene. Unsere Festungen dort sind schon ganz zu Anfang unseres Schlachtzugs gefallen, aber vielleicht können wir sie jetzt zurückfordern.", sourceObjective = "Sprecht mit Tortolla in der Verbrannten Ebene auf dem Hyjal.", completion = "{race}.\n\nIch erinnere mich an Euch. Retter meiner Kinder.\n\nDie Zeit ist gekommen. Für Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[25844] = { id = 25844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sättigt die wilde Bestie", description = "Ihr habt den Kommandanten gehört, {name}. Bringt mir das perfekte Geschenk für den Botschafter der Grimmtotem! Er wartet mit seinem Trupp am unteren Ende des südöstlichen Pfads.\n\nDas sollte unser Ansehen bei ihrem Häuptling steigern!", sourceObjective = "Bringt Ton Windbogen am Posten der Grimmtotem die fleischige Gabe.", progress = "<Ton Windbogen schnüffelt und hebt die linke Hand.>\n\nIhr habt etwas für uns dabei?", completion = "<Ton und seine Leibwächter verschlingen die fleischige Gabe.>\n\nEtwas... etwas so gutes habe ich noch nie gegessen. Vielleicht erweist Ihr Euch doch noch als wertvoller Verbündeter, aber bevor die Grimmtotem sich auf eine Zusammenarbeit mit der Allianz einlassen, müsst Ihr unseren Bedingungen zustimmen. Hier sind sie, so wie mein Anführer sie mir gesagt hat. Bringt sie Eurem Kommandanten. Mal sehen, ob er zustimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25845] = { id = 25845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forderungen", description = "Grimmtotem brauchen Waffen! Die Horde hat dank ihres Kriegshäuptlings und der Hilfe ihrer neuen Goblinverbündeten mächtige Waffen angehäuft. Unsere Kriegswerkzeuge haben dieser Feuerkraft nichts entgegenzusetzen. Stattet die Grimmtotem mit starken Waffen aus, dann werden wir gemeinsam die Horde vernichten!\n\nDies sind unsere Forderungen! Versorgt die Grimmtotem, dann kämpfen wir für die Allianz!", sourceObjective = "Bringt die Forderungen der Grimmtotem zu Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", progress = "Und???", completion = "Waffen, hm?\n\n<Truppenkommandant Valen seufzt.>\n\nIch werde jetzt eine spontane Entscheidung fällen, {name}. Ich hoffe, es ist die richtige, sonst wird mich König Wrynn einen Kopf kürzer machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25846] = { id = 25846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundig Finsterwolke, Häuptling der Grimmtotem", description = "Der Häuptling der Grimmtotem erwartet Euch, {name}. Nehmt die Waffenkisten und brecht zum Posten der Grimmtotem südlich von hier auf.\n\nViel Glück, {name}. Sollte Euch etwas zustoßen, werde ich persönlich Eure Angehörigen informieren und König Wrynn wissen lassen, was Ihr für die Allianz getan habt.", sourceObjective = "Bringt die Waffenkisten der Allianz zu Grundig Finsterwolke am Posten der Grimmtotem im Steinkrallengebirge.", progress = "Habt Ihr die Waffen?", completion = "Das sind gute Waffen! Mächtiger Stahl! Mit solchen Waffen werden meine Krieger unbesiegbar sein. Magatha lächelt auf Euch herab, {name}.\n\nIch möchte Euch um einen, vielleicht auch zwei Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25847] = { id = 25847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überlegenheit der Grimmtotem", description = "Überall im Hochwipfeltal werden Grimmtotem von der Horde angegriffen. Höllschreis Armeen kennen weder Gnade noch Mitgefühl. Sie töten jeden, der ihnen im Weg steht.\n\nDas muss ein Ende haben! Nehmt das Kriegswerkzeug, das Ihr uns gebracht habt und sucht nach Grimmtotem, die gegen die Horde kämpfen. Gebt ihnen die Waffen der Allianz und seht zu, wie sie die Angreifer der Horde vernichten! Geht. Es gibt viel zu tun, <Verbündeter/Verbündete>.", sourceObjective = "Bewaffnet 12 Grimmtotem mit der Waffenkiste der Allianz.", completion = "Der Kampf ist noch längst nicht vorbei, {name}. Die Hordengeneräle leben noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25848] = { id = 25848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergang", description = "Als wir erfuhren, dass Höllschrei einen weiteren Orc der Mag'har ausgesandt hatte, um die Hordentruppen im südlichen Steinkrallengebirge anzuführen, war es bereits zu spät. Camp Aparaje war niedergebrannt worden, alle Grimmtotem in dem Gebiet waren in den Flammen vergangen.\n\nVier der gefürchtetsten Hordengeneräle führen die Schlacht um das Hochwipfeltal an, unter ihnen auch der Mag'hargeneral Glubgok.\n\nReist nach Süden, zu den Ruinen von Camp Aparaje und tötet die Generäle. Wir halten die Horde JETZT auf! Kehrt zu mir mit ihrem Zeichen zurück!", sourceObjective = "Tötet die Hordengeneräle in Camp Aparaje und erbeutet das Insigne des Hordengenerals.", progress = "Sind die Generäle tot?", completion = "<Grundig zerquetscht das Insigne in seiner riesigen Faust.>\n\nIhr habt es geschafft, Verbündeter! Höllschrei wird Wochen brauchen, um sich von diesem Schlag zu erholen. Das südliche Steinkrallengebirge gehört den Grimmtotem... und der Allianz natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25849] = { id = 25849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Archäologie", description = "Hört zu, <mein Freund/meine Liebe>, jeder gute Archäologe kennt die Risiken seines Berufs. Wenn man nicht wenigstens einmal in seiner Karriere einen uralten Dämon ausgräbt oder von einem boshaften Geist verflucht wird, dann sucht man nur nach Plunder!\n\nWahre Archäologen wissen, dass Kleinigkeiten wie versteinerte Knochen, die zu Skelettkriegern reanimiert werden, kein Grund sind, die Arbeit einzustellen.\n\nDiese versteinerten Knochen brauche ich. Erbeutet sie von den Fossilienmonstern, die in der Gegend umherstreunen und bringt sie mir. Ich werde Euch belohnen.", sourceObjective = "Erbeutet 20 versteinerte Knochen von lebenden Fossilien.", progress = "Ihr müsst Euch nicht zurückhalten! Bringt mir, soviel Ihr tragen könnt!", completion = "Seht Ihr? Nicht schlecht, oder? Ich wünschte fast, all meine Funde würden sich selbst ausgraben. Würde mir die Arbeit erleichtern!\n\nIhr habt sie natürlich auch erleichtert, {name}. Besten Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[25850] = { id = 25850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt die Erde!", description = "Falls es Euch entgangen sein sollte, das Land hier im Sumpfland ist ziemlich chaotisch. Überflutungen, Erdbeben... und jetzt wird auch noch der Boden wild.\n\nIch hätte nie geglaubt, dass wir einmal von unserer Grabungsstelle angegriffen werden würden, aber seit kurzem laufen Erdschollen Amok und versuchen, jeden Zwerg zu zerquetschen, den sie finden können.\n\nIhr seht jung und kräftig aus, {race}... würdet Ihr dort hinunter gehen und diesen Klumpen etwas Verstand einprügeln?", sourceObjective = "Tötet 7 paläolithische Elementare.", completion = "Ihr habt es ihnen gezeigt! Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25851] = { id = 25851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit den Grimmtotem tanzt", description = "Kehrt zu Eurem Anführer zurück und berichtet ihm, was Ihr für die Grimmtotem getan habt. Sagt ihm, dass unsere Grenzen von nun an für die Allianz geöffnet sind.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Hervorragende Arbeit, {name}! Nun müssen sich unsere Streitkräfte nur noch beim Betreten des Steinkrallengebirges Sorgen wegen der Horde machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25852] = { id = 25852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles frei", description = "Packt Eure Sachen, {name}, wir werden uns jetzt den restlichen Streitkräften der Nordwacht im Südlichen Brachland anschließen. Eure erste Mission im Südlichen Brachland sollte recht unkompliziert sein.\n\nVor zwei Tagen erreichte uns ein Notruf von Kommandant Walpole. Man hat ihn und sein Bataillon auf dem Steinkrallenpass außerhalb von Ehrenwacht eingekesselt. Die Horde ist überall! Geht dorthin und helft ihm. Ich werde das Nordwachenkommando von unserer Allianz mit den Grimmtotem in Kenntnis setzen.", sourceObjective = "Meldet Euch bei Kommandant Thomas Walpole auf dem Steinkrallenpass im Südlichen Brachland.", completion = "Die Grimmtotem sind also keine Bedrohung mehr? Das ist gut, aber uns tritt hier gerade die Horde in den Hintern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25853] = { id = 25853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Hut und Peitsche", description = "Ich bin für die Ausrüstung dieser Ausgrabungsstätte verantwortlich. Das läuft ganz gut, aber die schnelle Abreise hat uns nicht gut getan!\n\nArchäologen brauchen schließlich Werkzeuge. Man kann unbezahlbare Antiquitäten nicht mit den Händen ausgraben. Wenn Ihr zur Ausgrabungsstätte reist, könntet Ihr uns das Werkzeug, das zurückgelassen wurde, mitbringen?", sourceObjective = "Beschafft 6 Archäologenwerkzeuge.", progress = "Sind sie vollständig? Wir haben einiges zurückgelassen.", completion = "Das erleichtert mich! Vielleicht können wir uns jetzt aus dem Mist graben, in dem wir bis zum Hals stecken.\n\nVergesst es, nur ein schlechter Scherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25854] = { id = 25854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich nenne ihn Bisschen", description = "Wusstet Ihr, dass manche Raptoren so intelligent sind, dass man sie zähmen kann? Das stimmt! Ich habe Jäger gesehen, die das getan haben.\n\nEs ist hier draußen ziemlich einsam, auch wenn Wenna mir Gesellschaft leistet... ein Haustier würde vielleicht meine Stimmung heben. Ein kleines Raptorbaby wäre toll!\n\nWenn Ihr ohnehin gerade dort draußen die Erwachsenen abschlachtet, könntet Ihr mir einige ausgebrütete Eier mitbringen? Die Eier wackeln, wenn die Babys schlüpfbereit sind.", sourceObjective = "Beschafft sechs wackelnde Raptoreneier.", progress = "Habt Ihr genug Eier? Das Risiko bei nur einem Ei ist zu hoch. Das ist statistisch erwiesen.", completion = "Wunderbar! Sie sollten noch heute schlüpfen...\n\nIch baue besser schon mal ein Gehege, bevor sie alle gleichzeitig schlüpfen. Eigentlich kann nichts schiefgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25855] = { id = 25855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dingsdabumse", description = "In letzter Zeit fehlen mir ständig Teile für meine Ingenieurskunstprojekte, und nun habe ich den Grund dafür entdeckt. Die Moosfellgnolle stehlen sie!\n\nIch weiß nicht, was sie damit wollen, aber ich muss diese Dingsdas wiederhaben. Wahrscheinlich liegen sie überall in den Sümpfen herum. Würdet Ihr sie mir mitbringen, wenn Ihr welche seht?", sourceObjective = "Findet 7 Dingsdas der Schnellschalts.", progress = "Habt Ihr sie gefunden?", completion = "Das ist wundervoll! Ich fange direkt mit dem Zusammenbau an. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[25856] = { id = 25856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenbälge", description = "Seit Jahren häute ich Krokis im Sumpfland, {class}. Es hat sich jedoch viel verändert.\n\nIch will nicht auf die Tränendrüse drücken, aber als der Kataklysmus den Hafen von Menethil überflutete, riss er auch unser Haus mit sich. Meine Frau und meine Kinder wissen nicht, wo sie bleiben sollen, und ich muss so viel Geld wie möglich verdienen, damit wir bald wieder ein Dach über dem Kopf haben.\n\nIch habe Krokis gehäutet, bis ich vor Müdigkeit umgefallen bin, aber ich brauche noch mehr Häute für den Verkauf. Bringt mir ein paar Krokibälge. Ich zahle Euch auch ein wenig dafür.", sourceObjective = "Erbeutet 10 Marschenkrokiliskenbälge von Sumpflandkrokilisken.", progress = "Habt Ihr Krokbälge für mich?", completion = "Ich bin Euch dankbar, {class}. Die werden meiner Familie helfen, wieder auf die Beine zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25857] = { id = 25857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt Horrorkiefer", description = "Es juckt mir in den Fingern, eine große Beute zu jagen... Horrorkiefer, den größten Krokilisken dort draußen. Mit seinem Balg könnte ich meine Familie aus diesem Loch holen.\n\nAber ich bin kein Narr. Ein Fehler reicht, um ein Bein oder gar mein Leben zu verlieren. Was würden meine Frau und Kinder dann tun? Sie wären immer noch obdachlos und die Kinder hätten keinen Vater mehr, der sich um sie kümmert.\n\nIch bin nicht stolz darauf, aber für die Sicherheit meiner Familie schlucke ich meinen Stolz hinunter. Bitte, {class}... jagt Horrorkiefer für mich. Er lauert im Norden, in seinem schattigen Tümpel.", sourceObjective = "Tötet Horrorkiefer und erbeutet Horrorkiefers Haut.", progress = "Habt Ihr sie? Habt Ihr Horrorkiefers Haut?", completion = "Unglaublich! Ihr seid ein wahrer Held, {name}. Ich werde nie vergessen, was Ihr für mich und meine Familie getan habt.\n\nIch weiß, dass es nicht viel ist, aber nehmt es mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25858] = { id = 25858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen der Lady", description = "Lady Sira'kess hat mit den Vorbereitungen für das Beschwörungsritual begonnen, aber der Schmelztiegel von Nazsharin wurde uns gestohlen. Sicher haben die Kvaldir ihn mit sich genommen, als sie sich in flachere Gewässer zurückgezogen haben.\n\nSprecht mit den Anführern der Kasten, um einen Kriegstrupp zusammenzustellen. Führt sie dann zum Biel'arangrat im Osten, um das Artefakt wiederzuholen.\n\nIch vertraue Euch, meine Kriegsmaid, denn Ihr habt mich noch nie enttäuscht, ganz gleich, welche Aufgabe ich Euch gab. So sehr die Königin mich schätzt, so sehr schätze ich Euch. Geht mit meinem Segen.", sourceObjective = "Sprecht mit Tiefenlord Zin'jatar, Lady Sira'kess und Aufseher Idra'kess.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Verstärkung zieht sich in den Gewässern um das Riff zusammen und macht sich für einen Angriff bereit. Sie warten nur noch auf Euren Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25859] = { id = 25859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Vergebung", description = "Ich weiß, dass Ihr genau wie unsere ehrwürdige Lady gelegentlich leider Anflügen von Mitleid unterliegt. Am heutigen Tage möchte ich Euch jedoch raten, diese Freundlichkeiten zu unterlassen. Die Kvaldir sind stolz. Wenn wir sie nicht komplett vernichten, werden sie ganz sicher Rache nehmen. Tötet alle, die Ihr finden könnt.\n\nLeider habe ich die ruhmlose Aufgabe sicherzustellen, dass keiner in die Stadt zurückkehrt, sodass ich Euch den ganzen Spaß überlassen muss. Ich werde Euch aber natürlich anfeuern.", sourceObjective = "Tötet 20 Kvaldir auf der Vrykulklippe.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Keiner ist zur Brücke entwischt. Nicht einer.\n\nWie langweilig. Nächstes Mal wäre ich Euch dankbar, wenn Ihr ein bisschen mit mir teilen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25860] = { id = 25860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koste es, was es wolle", description = "Wir beginnen sofort mit dem Ritual. Ihr werdet Euch darum kümmern, dass niemand uns unterbricht.\n\nErschlagt alle Kvaldir, die den Tempel betreten. Achtet darauf, dass meine Priesterinnen überleben, um ihre Aufgabe zu Ende zu bringen. Koste es, was es wolle.", sourceObjective = "Tötet 20 Angreifer der Kvaldir im Tempel von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Ich vertraue darauf, dass Ihr uns beschützt, Kriegsmaid.", completion = "Wenn Azjentus etwas verspricht, dann hält er es auch. Lady Naz'jars Ehrenwache sollte ausreichen, um den Rest des Rituals zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25861] = { id = 25861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Exempel statuieren", description = "Die Hochschamanen befinden sich in den Gebäuden in der Nähe und singen und spotten, trauen sich aber nicht, näher zu kommen. Diese Kvaldir sind nur mutig, wenn sie sich im Nebel verstecken können. Ein erbärmliches Ärgernis unter den Wellen.\n\nIch bringe eine Nachricht. Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", sourceObjective = "Bringt einen Hochschamanen der Kvaldir zu Henker Verathress' Füßen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", completion = "Meine Sense ist gesättigt. Vielen Dank, gnädige Frau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25862] = { id = 25862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Eigentum", description = "Unsere ehrwürdige Lady hat mich geschickt, um Euch bei Eurer Aufgabe zu helfen. Sie möchte, dass Ihr den gestohlenen Schmelztiegel von Nazsharin wiederbeschafft und so schnell wie möglich hierher bringt.\n\nSie kann es kaum erwarten, das Beschwörungsritual durchzuführen, damit wir endlich voll und ganz mit unseren Kriegsvorbereitungen beginnen können.", sourceObjective = "Besorgt den Schmelztiegel von Nazsharin.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "<Der Schmelztiegel sieht viel zu schwer aus, als dass Ihr ihn alleine tragen könntet, aber es sind mehr als genug Streitmächte der Naga übrig, um ihn für den Transport vorzubereiten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25863] = { id = 25863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Last", description = "Jetzt, da Ihr den Schmelztiegel von Nazsharin an Euch gebracht habt, müsst Ihr nur noch Lady Naz'jar von Eurem Erfolg berichten.", sourceObjective = "Kehrt mit Euren Nachrichten vom Schmelztiegel von Nazsharin zum westlichen Ende des Biel'arangrats zurück.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Gut gemacht, meine Kriegsmaid.\n\nDieser Schmelztiegel wird uns als Quell der Macht für unser Beschwörungsritual dienen. Damit wird Sira'kess unsere Verbündeten aus den Tiefen rufen, um unsere ohnehin schon starke Armee zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25864] = { id = 25864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaurierkrise", description = "Ständig erreichen uns Berichte über Raptorangriffe in der Gegend. Ich muss hier für Sicherheit sorgen, damit mehr Siedler kommen. Aus diesem Grund habe ich ein Kopfgeld auf diese Viecher ausgesetzt.\n\nViele wurden bereits beseitigt, aber die Hochlandraptoren im Norden vermehren sich stark. Aber das wird sich bald ändern, nicht wahr?\n\nErledigt ein paar Hochlandraptoren, dann gebe ich Euch eine hübsche Belohnung.", sourceObjective = "Tötet 8 beliebige Hochlandraptoren.", completion = "Gute Arbeit. Betrachtet das nicht als Belohnung von mir, sondern von Eisenschmiede. Der Erhalt von Khaz Modan geht jeden Zwerg etwas an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25865] = { id = 25865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Moosfellmission", description = "Ihr wirkt vertrauenswürdig. Würdet Ihr mir bei meinem wahren Problem helfen, {name}? Eisenschmiede hat mich hierher geschickt, um eine Lieferung Goldbarren wiederzubeschaffen.\n\nDie Barren gehören zum Thronschatz von Eisenschmiede und tragen das königliche Siegel. Nur ein Narr würde sie aus Profitgier stehlen. Sie sind viel zu leicht nachzuverfolgen. Wie es der Zufall will, gibt es jede Menge Narren hier: Moosfellgnolle.\n\nIch weiß nicht, wie oft Ihr schon gegen Gnolle gekämpft habt, aber das sind üble und brutale Bestien. Sie sind gefährlich. Tötet sie und bergt die verschwundenen Barren.", sourceObjective = "Beschafft 8 Barren von Eisenschmiede von den Gnollen der Moosfelle.", progress = "Es wurden schätzungsweise acht Barren gestohlen.", completion = "Gut gemacht! Die Wache von Eisenschmiede dankt Euch, {name}. Ihr habt unserer Stadt einen großen Gefallen erwiesen.\n\nDoch es gibt neue Probleme...", sourceObjectiveStatus = "unverified-source-field" }
quests[25866] = { id = 25866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallensteller der Dunkeleisenzwerge", description = "Der Klan der Dunkeleisenzwerge ist in diesem Gebiet gesehen worden. Vielleicht sind sie Euch schon über den Weg gelaufen. Sie führen nie Gutes im Schilde, und dieses Mal scheinen sie aus irgendeinem Grund Moosfellgnolle zu entführen.\n\nIch weiß nicht, was das soll, aber wir müssen sie aufhalten, bevor noch üblere Dinge geschehen. Haltet sie auf.\n\nWenn Ihr Euch Sorgen macht, weil das unfair ist, könnt Ihr sie ja zuerst höflich fragen. Mal sehen, wie weit Ihr damit kommt.", sourceObjective = "Tötet 10 Fallensteller der Dunkeleisenzwerge.", completion = "Ich nehme an, sie sind nicht freiwillig mitgekommen? Dachte ich mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25867] = { id = 25867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht der Gnolle", description = "Ich weiß, dass wir selbst gerade die Gnolle angegriffen haben, aber ich werde nicht zulassen, dass die Dunkeleisenzwerge sie als Sklaven halten. Zum einen haben wir die Diebe gefunden und unseren Besitz zurückerhalten, also wurde der Gerechtigkeit Genüge getan. Zum anderen werden die Dunkeleisenzwerge sie bestimmt nicht für gemeinnützige Arbeiten einsetzen... \n\nAlso müssen die Gnolle befreit werden. Die Fallensteller sollten die Schlüssel, mit denen man die Käfige öffnen kann, bei sich tragen.", sourceObjective = "Erbeutet den Schlüssel des Fallenstellers von Fallenstellern der Dunkeleisenzwerge und befreit damit 6 Gnolle aus den Gnollkäfigen.", completion = "Das sollte reichen! Je mehr Gnolle diese Narren jagen müssen, desto leichter wird es, sie in Schach zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25868] = { id = 25868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorla Dunkelschlinge", description = "Ich habe herausgefunden, wer bei dieser Operation im Hintergrund die Fäden zieht. Yorla Dunkelschlinge führt die Dunkeleisenzwerge von einem Lager im Osten an. Wahrscheinlich hat sie den Gnollen befohlen, das Gold aus Eisenschmiede zu stehlen.\n\nAußerdem ist sie eine gesuchte Kriminelle... Schon als Magni noch lebte, schürte sie Rebellionen und Angriffe gegen Eisenschmiede.\n\nDieses Mal wird sie uns nicht durch die Lappen gehen, {name}. Schnappt sie Euch!", sourceObjective = "Tötet Yorla Dunkelschlinge.", completion = "Gute Arbeit! Ihr habt eine der größten Verbrecherinnen Eisenschmiedes der Gerechtigkeit zugeführt, {name}. Ihr habt Euch eine ziemlich große Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25869] = { id = 25869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Freiwindposten", description = "Die Reise, die vor uns liegt, beginnt damit, dass Ihr alle Eindringlinge der Grimmtotem in Freiwindposten tötet. Wenn Ihr sie hier nicht aufhalten könnt, werden wir nicht in der Lage sein, bis zu ihrem Territorium vorzudringen.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotem.", completion = "Bei dieser Aufgabe kann man wirklich nur grimmig dreinschauen.<Quentin hustet.>\n\nNein, das war nicht witzig gemeint.", sourceObjectiveStatus = "unverified-source-field" }
quests[25870] = { id = 25870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Freiwindposten", description = "Ihr müsst die Eindringlinge der Grimmtotem in Freiwindposten loswerden. Das haben sie sich aber selbst zuzuschreiben, diese Feiglinge!\n\nWir können nicht zulassen, dass die Schlacht in ihre eigenen Gebiete verlagert wird, und wir sprichwörtlich mit dem Rücken zu ihnen stehen. Bitte helft uns, unsere Heimat zurückzuerlangen, {class}.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotem.", completion = "Das ist schon mal ein guter Anfang! Normalerweise würde ich keiner Kreatur der Erdenmutter irgendein Leid wünschen.\n\nAber da sie uns zu einem Zeitpunkt extremer Verletzlichkeit angegriffen haben, verdienen sie den Tod!", sourceObjectiveStatus = "unverified-source-field" }
quests[25871] = { id = 25871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Schildwache", description = "<Brienna wedelt mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben eine unserer Schildwachen gefangen! Sie drohen damit, sie zu töten, wenn wir uns nicht zurückziehen!\n\nWir verhandeln nicht mit feigen Bestien! Bitte {class}, könnt Ihr versuchen, die Schildwache zu retten, bevor es zu spät ist?", sourceObjective = "Rettet die Schildwache von Feralas.", completion = "Danke, dass Ihr die sie befreit habt, {name}. Die Monster der Grimmtotem hätten sie sicherlich kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25872] = { id = 25872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegerheld und die Wagemütigen", description = "<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!\n\nWir werden diesen feigen Grimmtotem nie gestatten, Freiwindposten zu behalten! Bitte {class}, rettet ihn, bevor es zu spät ist.", sourceObjective = "Retten den Kriegerheld des Freiwindpostens.", completion = "Vielen Dank {name}, dass Ihr den Kriegerhelden befreit habt. Diese Grimmtotem hätten ihn kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25873] = { id = 25873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "Was ist das, {class}?", completion = "Ein Verräter unter den Tauren?\n\nVon so etwas habe ich noch nie etwas gehört. Rivalitäten und Kriege zwischen den Klans sind eine Sache, aber das kaltblütige Töten eines Verbündeten ist etwas anderes.\n\n<Quentin schüttelt ungläubig seinen Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25874] = { id = 25874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "{name}? Habt Ihr Neuigkeiten?", completion = "Der Klippenbehüter war ein Spion der Grimmtotem?! Kein Wunder, dass wir nicht gewarnt wurden!\n\n<Thalia schäumt beinahe über vor Wut.>\n\nDieses verdammte Horn will ich nicht. Lasst es in den Tiefen des Wassers untergehen, und sorgt dafür, dass der Name Langhorn nie wieder erwähnt wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[25875] = { id = 25875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eingeschleuste Gnom", description = "Am Mirkfallonsee wimmelt es von der Horde. Die Goblins haben sich dort eingenistet, und sie werden erst wieder abziehen, wenn sie das gesamte Öl unter dem Steinkrallengebirge ausgesaugt haben.\n\nZum Glück konnte ich einen Gnom einschleusen, der Informationen für uns sammelt. Wenn irgendjemand weiß, was es mit dieser Bombe auf sich hat, dann mein eingeschleuster Gnom.\n\nGeht zu den Schlickwerken im Norden und findet Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", sourceObjective = "Sucht in den Schlickwerken im Steinkrallengebirge nach Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", completion = "Kommt rein und bleibt an der Wand! Meine Tarnung darf nicht auffliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25876] = { id = 25876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie ist da oben!", description = "Ich folge dieser Bombe, seit Ihr mich in Eschental gerettet habt. Was auch immer sie damit vorhaben, wird bald geschehen.\n\nGanz oben auf der großen Ölplattform gibt es einen Kontrollraum. Im Kontrollraum werdet Ihr das Logbuch von Krom'gar finden. Dieses Logbuch ist der Schlüssel zum Ziel der Bombe. Geht nach oben und holt das Logbuch! Bringt es hierher. Ich werde es für Euch dechiffrieren.", sourceObjective = "Stehlt das Logbuch von Krom'gar.", progress = "Habt Ihr das Logbuch bekommen?", completion = "OH NEIN! Sie wollen die Bombe im Hain von Thal'darah \"testen\"! Das ist eine Schule für junge Druiden mitten im Kriegsnarbental. Ihr müsst zu Barus zurückkehren und ihn davon unterrichten! Meister Thal'darah muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25877] = { id = 25877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Verabschiedungen!", description = "LAUFT! Verschwindet hier, {name}. Sucht Barus auf und sagt ihm, was Ihr herausgefunden habt. Er wird dafür sorgen, dass Ihr sicher durch das Kriegsnarbental zur Aussicht von Thal'darah gelangt.\n\nFür diese jungen Druiden ist es noch nicht zu spät!", sourceObjective = "Kehrt zu Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge zurück", completion = "Verdammte Horde! Ich habe Freunde in diesem Hain. Ich hoffe, Ihr könnt auf einem Hippogryph reiten. Ihr müsst sofort zu Meister Thal'darah an der Aussicht aufbrechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25878] = { id = 25878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Sabotage", description = "Goblins... Was wäre die Welt ohne Goblins? Das kann ich Euch sagen: SAUBER!\n\nDiese schmutzigen kleinen Unholde haben überall auf dem See Ölpumpen errichtet, mit denen sie das Öl im Streinkrallengebirge bis auf den letzten Tropfen abzapfen wollen. An jeder Ölpumpe steht ein Ölpumpenkontrolleur, der darauf achtet, dass die Pumpe läuft und nichts schief geht.\n\nAber etwas wird schiefgehen.\n\nBeseitigt die Goblinpumpenkontrolleure und nehmt ihre Pumpensteuerung. Überlastet damit die Pumpen!", sourceObjective = "Zerstört 4 Goblinölpumpen mit der Goblinpumpensteuerung.", completion = "Ich konnte die Explosionen von hier sehen, {name}! Dank Euch wird die Horde keinen Treibstoff mehr vom Mirkfallonsee bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25879] = { id = 25879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger mit den Trampeln", description = "Schon mal einen Hobgoblin gesehen? Das ist wieder so eine eklige Schöpfung der Goblins. Nehmt einen Goblin, macht ihn noch hässlicher, fetter, größer und dümmer, und heraus kommt ein Hobgoblin. Fügt dem noch einen miesen Charakter hinzu, dann versteht Ihr das Problem.\n\nDiese Trampel lungern an den Schlickwerken und am Mirkfallonsee herum. Die Goblins setzen sie als Wächter ein.\n\nGeht dorthin und dünnt sie etwas aus. Unwiderruflich.", sourceObjective = "Tötet 10 Trampel.", completion = "Langsam, aber sicher führen wir der Horde Verluste zu. Sie werden kein Bein auf den Boden kriegen, wenn es in diesem Krieg richtig zur Sache geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25880] = { id = 25880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Meister Thal'darah", description = "Im Hain von Thal'darah leben Dutzende Schüler. Die meisten können sich nicht wehren. Man wird sie abschlachten.\n\nInformiert Meister Thal'darah über die Pläne der Horde. Er wird Euch erklären, was als Nächstes zu tun ist.\n\nFiora Mondsegler hat Euch ihren schnellsten Hippogryph gegeben. Fliegt damit zur Aussicht von Thal'darah! Seht nicht zurück, {name}! Die Horde muss aufgehalten werden!", sourceObjective = "Meldet Euch bei Meister Thal'darah an der Aussicht von Thal'darah im Steinkrallengebirge.", completion = "Wir leben in wirklich schlimmen Zeiten, {name}. Unser Außenposten auf dem Steinkrallengipfel wurde von grausamen Kreaturen aus der Tiefe überrannt, und die Horde will uns vernichten. Wir brauchen einen Helden, {name}; einen Soldaten der Allianz, der uns sicher durch diese schweren Zeiten führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25881] = { id = 25881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Wächter", description = "Wir haben so lange durchgehalten wie es ging, {class}. Aber die Flammen… die Hitze… Wir haben die Stadt ganz verloren.\n\nHauptmann Eisenstamm hat sich geweigert, zum Rückzug zu blasen, als die Flammen uns eingeschlossen haben. Unsere Truppen sind überall verstreut. Vielleicht haben ein paar der anderen überlebt? Wir könnten einen Gegenangriff starten!\n\nReist in die Verbrannte Ebene und rettet alle verschollenen Wächter, die von ihrer Gruppe getrennt wurden. Dann sucht nach Hauptmann Eisenstamm. Er befindet sich wahrscheinlich mitten im Kampfgetümmel.", sourceObjective = "Findet und rettet 8 verschollene Wächter.", completion = "Ihr habt die Überlebenden versammelt? Gut, gut. Und der Rest des Berges… ist geheilt?\n\nHa, da brat mir einer einen Storch! Wir sind wieder an der Front!", sourceObjectiveStatus = "unverified-source-field" }
quests[25882] = { id = 25882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Gehöft", description = "Hauptmann Tharran hat mich gebeten, Euch seinen Dank für Eure Hilfe und seine Glückwünsche zur erfolgreichen Mission auszurichten. Er kümmert sich mit seinen Männern um die letzten Trolle und versorgt die Verwundeten.\n\nEr hat mich auch gebeten, Euch zu fragen, ob Ihr Berichten über Trollüberfälle auf dem Gehöft Bernruh im Norden nachgehen könntet. Fragt nach Unteroffizier Flinthammer, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Unteroffizier Flinthammer auf dem Gehöft Bernruh.", completion = "Ihr habt also Hauptmann Tharran dabei geholfen, die Frostmähnentrolle zurückzuschlagen? Ich habe Euren Namen in den Berichten gesehen. Freut mich, Euch endlich kennenzulernen. Ein {class} wie Ihr könnte zur Sicherung des Gehöfts eine echte Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25883] = { id = 25883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnend", description = "Nagawaffen…\n\nAls Ihr Euren Blick über die Pferche streifen lasst, seht Ihr Dutzende ähnlicher Dreizackstapel, die strategisch positioniert zu sein scheinen.\n\nIhre Waffen zu zerstören behindert sicher die bösen Pläne, die sie in dieser Gegend verfolgen...", sourceObjective = "Zerstört 6 Dreizackstapel der Naga.", progress = "Habt Ihr das Waffenlager der Naga zerstört?", completion = "Ihr seid Euch sicher, dass Eure Zerstörung der Waffen die Naga sicher stark einschränken wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25884] = { id = 25884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Biegen und Brechen", description = "Himmeldonnerwetter nochmal...\n\nIch weiß, dass unser Schiffbrüchiger hier es gut meint, aber der Junge ist doch schwerst traumatisiert.\n\nEs gibt nur eine Methode, wie man mit diesen verflixten Biestern fertig wird, und zwar indem man ihnen eine anständige Zwergenaxt bis zum Anschlag in den Schädel rammt.\n\nJe mehr Leichen ihrer Kameraden man vor ihnen aufstapelt, desto genauer werden sie es sich überleg'n, einem ans Leder zu geh'n.\n\nDas könnt Ihr mir glaub'n, <Kumpel/Mädel>, die Burschen mög'n den Anblick ihres eigenen Blutes genausowenig wie Ihr oder ich.\n\nUnd jetzt ab mit Euch und zeigt denen, was 'ne Harke ist!", sourceObjective = "Tötet 12 Naga des Zin'jatar in der Umklammerung im Tang'tharwald.", completion = "Die Gewässer in der Umgebung der Pferche färben sich rot vom Blut der Naga.\n\nRendel wäre stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25885] = { id = 25885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {class}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25886] = { id = 25886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Vorteil nutzen", description = "Wie es scheint, hat ein Großteil des Schattenhammers sich zurückfallen lassen, um sich für einen weiteren Angriff neu zu formieren. Nur ihre besten Kämpfer halten noch die Front. Dies ist unsere Gelegenheit, um ihren Anführern den Garaus zu machen.\n\nSchwärmt aus über die Verbrannte Ebene und vernichtet die Zwielichtfeldhauptmänner. Wir werden sie von dieser Welt tilgen!", sourceObjective = "Tötet 4 Zwielichtfeldhauptmänner.", completion = "Ausgezeichnet! Der Schattenhammer wird zweifellos versuchen, den Berg zurückzuerobern, aber dafür müssen sie jetzt auf die Führerschaft dieser hirnlosen Muskelpakete verzichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25887] = { id = 25887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welle der Zerstörung", description = "Unsere Zeit hier neigt sich dem Ende zu. Ich muss diesen Nagaflüchtlingen irgendwie folgen, wenn wir herausfinden wollen, was sie in dieser Gegend vorhaben.\n\nAber bevor ich weiterziehe will ich sehen, wie dieser Ort hier vernichtet wird!\n\nEgal, wie viele es sind, ich habe einen Plan, der für Chancengleichheit sorgen wird.\n\nAußerhalb der Höhle suchen ausgemergelte große Haie, die von den Naga vertrieben wurden, nach Nahrung.\n\nIn ihrem geschwächten Zustand sind sie für Anregungen sehr empfänglich. Benutzt diese Kugel, um sie zu unterwerfen und hetzt sie dann direkt auf unseren Feind.", sourceObjective = "Benutzt die Kugel der Anregung, um einen ausgemergelten großen Hai zu unterwerfen und benutzt ihn dann, um 12 Gefolgsleute des Zin'jatar in der Umklammerung zu töten.", completion = "Genau so soll es sein.\n\nJetzt ist der Weg frei, um diesen Naga einen letzten vernichtenden Schlag zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25888] = { id = 25888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Soldat inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Soldaten in der Umklammerung.", progress = "Konntet Ihr einige der eingekerkerten Soldaten retten, {name}?", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25889] = { id = 25889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kinder!", description = "Meine armen, hilflosen Schüler sitzen im Hain von Thal'darah fest. Wegen der Schlacht, die im Kriegsnarbental tobt, können sie nicht entkommen. Wir müssen die Kinder retten, bevor die Horde ihre Bombe abwirft!\n\nNehmt meinen Hippogryph und rettet damit die jungen Druiden im Hain von Thal'darah. Setzt sie am Hippogryphenposten hier in der Stadt ab.\n\nRettet sie alle, {name}! Ihr seid wahrlich unsere einzige Hoffnung.", sourceObjective = "Rettet mit Meister Thal'darahs Hippogryph 5 hilflose junge Druiden aus dem Hain von Thal'darah.", completion = "Habt Dank, {name}. Der Held, auf den wir gewartet haben, ist endlich gekommen - und keinen Augenblick zu früh.", sourceObjectiveStatus = "unverified-source-field" }
quests[25890] = { id = 25890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nespirah", description = "Jetzt ist mir klar, was wir tun müssen, {name}.\n\nDie Naga können diese Perlen nur von einem Ort haben: Nespirah, das uralte Schalenwesen, das außerhalb dieser Höhle ruht. Warum Nespirah sich den Naga unterwirft, ist mir allerdings schleierhaft.\n\nWir können durch eine kleine Röhre in der Nähe des Ausgangs dieser Höhle in Nespirahs Körper eindringen. Ich muss zuerst noch meinen Meister holen, danach können wir uns im Inneren treffen. Wir werden Nespirah durch den nordwestlichen Eingang betreten.", sourceObjective = "Betretet Nespirahs nordwestlichen Eingang und findet dann einen Weg, um mit ihr zu sprechen.", completion = "Erunak vertraut diese Aufgabe mir an? Nun gut. Mal sehen, was wir von der Ahnin lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25891] = { id = 25891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Letzte Anstrengung", description = "Die Horde signalisiert den Rückzug. Seht, wie sie das Schlachtfeld verlassen - das ist der Vorbote einer Katastrophe.\n\nWir müssen ein letztes Mal im Hain von Thal'darah landen. Ich würde es nicht ertragen, wenn auch nur ein junger Druide zurückbleiben müsste.\n\nHelft mir, <Held/Heldin>. Ich nehme die Zügel. Sucht Ihr nach Druiden, die vielleicht zurückgelassen wurden.\n\nWir brechen auf, wenn Ihr bereit seid.", sourceObjective = "Helft Meister Thal'darah bei der Suche nach Druiden, die im Hain von Thal'darah zurückgelassen wurden.", completion = "Wisst Ihr, weshalb die Horde zerstört? Die Horde zerstört, weil sie Schönheit nicht begreifen kann. Sie fürchtet sie, und was sie fürchtet, muss sie zerstören. Warum sonst zerstört sie den Hain von Thal'darah?\n\nGemeinsam werden wir dafür sorgen, dass sie etwas verstehen. Sie werden verstehen, dass ihre Taten einen hohen Preis fordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25892] = { id = 25892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt Wellensprecherin Valorens Seepferd, um zu Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Freut mich sehr, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25893] = { id = 25893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Jorlan und Hexasept sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Ingenieur Hexasept auf dem Biel'arangrat.", completion = "Pünktlich wie ein Uhrwerk! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Uhrwerk!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25894] = { id = 25894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Hexasept kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Kiemengoblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Kiemengoblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25895] = { id = 25895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Wir müssen immer vorbereitet sein. Wir müssen Ausrüstung haben. Wir müssen Pläne haben!\n\nAlle Schiffe in der Flotte der Allianz sind mit einer Überlebensausrüstung ausgestattet. Viele unserer Werkzeuge stammen aus so einer Überlebensausrüstung. Mein Ballon war auch in so einer Überlebensausrüstung enthalten! Aber jetzt ist sie aufgebraucht. Ich brauche noch eine Überlebensausrüstung!\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren und die Überlebensausrüstung nicht mitgenommen haben. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Allianz.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25896] = { id = 25896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andächtige Versammlung", description = "Ah, Kriegsmaid. Das Wort und der Wille unserer Lady sind mit Euch. Ich möchte Euch um einen Gefallen bitten…\n\nTiefenrufer Azrajar und meine Gezeitenpriesterinnen müssen zurückkehren, damit wir mit dem Ritual beginnen können. Könnt Ihr ihnen meinen Wunsch überbringen? Ihr solltet sie auf der Tempelterrasse und den Treppen unten finden. Azrajar hält sich an der Treppe im Norden auf.", sourceObjective = "Sucht Tiefenrufer Azrajar in der Mitte der nördlichen Treppe sowie 6 Gezeitenpriesterinnen der Sira'kess auf der oberen Ebene der Ruinen und tragt ihnen auf, zum Tempel zurückzukehren.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Die Bedrohung ist vielleicht nicht gewiss, aber die Kvaldir sind keine Narren. Sie würden nicht zurückkehren, wenn sie nicht zumindest ein wenig an ihren Sieg glauben würden.\n\nJe schneller unsere Verbündeten gerufen werden können, umso besser. Sucht nach meinen Gezeitenpriesterinnen.", completion = "Die Kvaldir haben sich als größere Bedrohung herausgestellt, als wir dachten. Aber unsere Pläne konnten sie nicht im Geringsten vereiteln. Wenn unsere Verbündeten eintreffen, werden wir mehr als genug Streitkräfte haben, um den Gezeitenjäger zu stürzen.\n\nWir müssen nur sicherstellen, dass das Beschwörungsritual abgeschlossen werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25897] = { id = 25897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Überhaupt keinen!\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Unbedingt!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25898] = { id = 25898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Welch günstiger Zufall.\n\nJorlan ist bereits nach oben geschwommen, um ihn zu packen. Ist hochgeschwommen und wartet jetzt dort. Er meinte aber, er würde Euch die Ehre überlassen. So ist Jorlan eben.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Allianz Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Allianzschiffe.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25899] = { id = 25899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Die flammende Armee, die oben auf dem Hügel so viel Verwüstung angerichtet hat, hat sich in den Osten zurückgezogen. Nur die sengenden Fürsten sind noch zugange. Wenn wir ihre Reihen durchbrechen könnten, um uns mit Hauptmann Eisenstamms Truppen zusammenzutun, könnte ihre gesamte Offensive scheitern.\n\n{class}, ich bin nicht in der körperlichen Verfassung, noch weiter zu kämpfen, aber Ihr seht aus, als könntet Ihr ihnen noch die ein oder andere Blessur zufügen. Tötet diese sengenden Fürsten und formiert Euch mit Hauptmann Eisenstamm neu!", sourceObjective = "Tötet 10 sengende Zwielichtfürsten.", completion = "Wie viele habt Ihr getötet? Sieh mal an. Ein beeindruckendes Schauspiel. Ich schätze, meine Männer haben jetzt keine Ausreden mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25900] = { id = 25900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ich kann mir kaum vorstellen, dass Nespirah freiwillig zulässt, dass diese Naga in ihrer Schale ihr Lager aufschlagen. So wie ich das sehe, ist eines von zwei Dingen geschehen: Entweder haben sie sie überzeugt, sich ihrer Sache anzuschließen, oder sie haben sie so geschwächt, dass sie sich nicht wehren kann. Beide Möglichkeiten sind nicht gut.\n\nHier in diesem Raum sollte ich direkt mit Nespirah kommunizieren können. Finden wir es also selbst heraus. Sprecht mit mir, wenn Ihr bereit seid, {class}.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", progress = "Nespirah braucht unsere Hilfe. Zumindest das spüre ich ganz deutlich.", completion = "Das ist nicht so gut gelaufen. Aus irgendeinem Grund antwortet das Geschöpf mir nicht.\n\n<Duarn ist sichtlich frustriert.>\n\nWenn Erunak uns nur nicht verlassen hätte! Er wüsste sicher, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25901] = { id = 25901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung auf dem Hyjal", description = "Verstärkung! Ich dachte, wir müssen hier bis zum bitteren Ende kämpfen.\n\nEs sind nur noch wenige Wächter des Hyjal übrig. Zudem gehen uns langsam aber sicher die Vorräte aus. Auf dem Schlachtfeld um unsere letzte Bastion herum sollte eine Unmenge noch funktionstüchtiger Pfeile herumliegen.\n\nIch weiß, dass es für jemanden mit Euren Fähigkeiten fast schon lächerlich einfach ist, aber könntet Ihr unsere gebrauchte Munition aufsammeln? Nur so können wir unsere Vorräte aufstocken.", sourceObjective = "Sammelt 15 Pfeile des Aufsehers.", progress = "Pfeile des Aufsehers werden aus lebender Eiche geschnitzt und in den Mondbrunnen gesegnet. Ihre Pfeilspitzen bestehen aus Obsidian, das mit Runen verziert ist, die den Segen der Natur beschwören.\n\nSie sind nicht gerade billig.", completion = "Wunderbar! Immer noch scharf. Die Befiederung ist ein wenig blutig, aber sie fliegen noch gerade.\n\nDanke, {name}. Jetzt können wir den Hyjal weiter verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25904] = { id = 25904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer und der Schlüssel", description = "Meine Nemesis. Ist noch am Leben.\nDie Diener des Feuers noch auf dem Vormarsch.\nWir müssen ihnen folgen. In ihren Bau.\n\nDie Oger kennen den Weg.\nTötet die Feldhauptmänner.\n\nBergt die Glyphe des Öffnens.\n\nSo soll es sein.", sourceObjective = "Tötet einen Zwielichtfeldhauptmann und besorgt Euch die Glyphe des Öffnens.", progress = "Die Glyphe. Zeigt sie mir.", completion = "Diese Macht ist uralt.\nPrimitiv.\nEinfach.\n\nWir werden sie gegen sie einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25905] = { id = 25905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widder auf der Flucht", description = "Die Widder, die wir hier auf dem Gehöft Bernruh züchten und ausbilden, werden von den Gebirgsjägern von Dun Morogh als Reittiere verwendet. Ja, es sind ein paar hier, aber nicht genug, um meine Familie und all die Tiere zu schützen.\n\nEinige mutige Frostmähnenräuber stehlen in letzter Zeit unsere Widder im Schutz der Nacht und bringen sie nach Süden in die Tundridhügel. Würdet Ihr uns helfen, sie zurückzuholen? Geht nah an sie heran und stoßt einen schrillen Pfiff aus, um ihre Aufmerksamkeit zu erregen. Den Rest erledigt ihre Ausbildung.", sourceObjective = "Benutzt /pfeifen, um 6 gestohlene Widder aus den Tundridhügeln zurückzuholen.", completion = "Die Widder, die Ihr gerettet habt, sind in ihren Stall zurückgekehrt. Meine Familienmitglieder werden sie ab jetzt Tag und Nacht bewachen. Diese Trolle werden uns nicht noch einmal übertölpeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[25906] = { id = 25906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dritte Flammentor", description = "Prägt Euch die Glyphe ein.\nNehmt sie mit Euch.\nZeichnet sie auf den Boden vor dem Flammentor.\nÖstlich von hier.\nBetretet die Feuerlande.\n\nIch kann nicht mit Euch kommen.\nAber meine Kinder erwarten Euch.\n\nSucht Garunda Bergkuppe im Reich der Flammen.", sourceObjective = "Reist durch das Flammentor in der Verbrannten Ebene und sucht nach Garunda Bergkuppe.", completion = "Der Schildkrötengott hat Euch geschickt? Gepriesen sei sein heiliger Panzer! Ich dachte, ich wäre hier unten für immer gefangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25907] = { id = 25907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklavenarbeit", description = "Ich werde ein wenig Zeit benötigen, um diese Barriere zu durchbrechen und mit Nespirah zu kommunizieren. In der Zwischenzeit könnt Ihr einige der Männer retten, die die Naga in den Gruben unter uns versklavt haben.\n\n<Duarn holt ein langes Seil aus seinen Roben hervor.>\n\nDas wird Euch sicher gute Dienste leisten.", sourceObjective = "Benutzt Duarns Seil, um 8 versklavte Perlenminenarbeiter zu retten.", completion = "Ausgezeichnete Arbeit, {name}… Obwohl ich fürchte, dass ich nicht annähernd so produktiv war wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25908] = { id = 25908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestraft sie", description = "Ich kann vielleicht nicht direkt mit Nespirah kommunizieren, aber ich kann zumindest indirekt etwas spüren. Zum Beispiel fühle ich deutlich, dass Nespirah alles andere als glücklich über die Anwesenheit der Naga hier ist.\n\nAls wir in Nespirahs Körper eingedrungen sind, sah ich Dutzende von Schildwachen und Verzauberinnen, die im zentralen Raum patrouillieren. Vielleicht könnt Ihr das Leid der Ahnin lindern, indem Ihr ihre Zahlen verringert.", sourceObjective = "Tötet 7 Schildwachen des Idra'kess und 7 Verzauberinnen des Idra'kess.", completion = "Könnt Ihr es fühlen? Wenn Ihr nur einen Tropfen Schamanenblut in Euch tragt, müsst Ihr das Gefühl der Erleichterung in der Luft spüren.\n\nNespirah ist erfreut. Vielleicht spricht sie jetzt endlich mit uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[25909] = { id = 25909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25910] = { id = 25910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit für Gnade ist vorbei", description = "Diese Höhle ist der reinste Höllenschlund, {name}. Sie ist voller abscheulicher Schrecken aus der Tiefe.\n\nIch möchte nicht, dass diese… Kreaturen… durch das Portal in die Außenwelt gelangen. Tötet sie alle!", sourceObjective = "Tötet 10 geschmolzene Peiniger und 4 Meister der Schattenflamme.", completion = "Also ist es vollbracht.\n\nDas Wissen, dass der Schattenhammerkult gemeinsame Sache mit solch abstoßenden und bösartigen Wesen macht… bringt mein Blut zum Kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25911] = { id = 25911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Kapitän Taylor am Stillen Strand zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ich weiß nicht, wie ich Euch für all das belohnen kann, das Ihr in diesem Meer getan habt, aber ich werde mir etwas einfallen lassen.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25912] = { id = 25912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute alte Zeit", description = "Die Welt gerät aus den Fugen, {name}. Vertraute Feinde versuchen uns an einer Seite zu zerstören, während uralte Kräfte uns von der anderen bedrängen.\n\n<Urahnin Sareth'na seufzt.>\n\nIch habe bessere Zeiten erlebt - hellere Tage, und ich sehne mich nach ihnen...\n\nHinter dem Steinkrallengipfel stehen die Ruinen unseres alten Außenpostens - die Dunkelheit hat ihn überrannt. Solltet Ihr Euch in dieser Gegend aufhalten, könntet Ihr dann nach meinem Zeichenbuch suchen? Es steckt voller glücklicher Erinnerungen. Ich würde Euch gut für seine Rückgabe belohnen.", sourceObjective = "Findet das Zeichenbuch der Urahnin Sareth'na.", progress = "Habt Ihr mein Zeichenbuch gefunden?", completion = "Ihr habt es gefunden! Möge Elune Euch segnen, Kind! Vielleicht verleiht mir dieses Buch die Kraft weiterzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25913] = { id = 25913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe", description = "Als die Horde ins Steinkrallengebirge einmarschierte, fiel mir auf, dass einige der Schildwachen krank wurden. Kurz darauf verhielten sie sich seltsam. Als der erste Tentakel aus dem Boden schoss, griffen die kranken Schildwachen uns an. Wir verloren den Außenposten kurz danach...\n\nDie Schildwachen im Gipfel sind nur noch Hüllen. In ihnen steckt etwas Böses. Bettet die Schildwachen zur letzten Ruhe und bringt ihre Gleven an Euch. Mit jeder zurückgebrachten Gleve kann eine gefallene Schwester identifiziert werden.", sourceObjective = "Bergt 8 Schildwachengleven.", progress = "Bergt die Schildwachengleven, {name}. Jede Gleve lässt sich einer Schildwache zuordnen.", completion = "Danke, {name}. Auf jede der Gleven ist der Name ihrer Besitzerin eingestanzt. Jetzt können wir ihre Familien benachrichtigen und ihren Seelen Frieden geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25914] = { id = 25914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Tiefe!", description = "Ranken schießen aus dem Boden und terrorisieren den Steinkrallengipfel. Meine Schildwachen werden ihrer nicht Herr.\n\nIch vermute, dass es im Herzen des Steinkrallengipfels eine Macht gibt, die diese Ranken kontrolliert. Wenn wir diese Macht aufhalten, werden die Ranken vielleicht in die Tiefen zurückkehren, aus denen sie gekommen sind.", sourceObjective = "Tötet Aph'lass und 10 einfallende Tentakel.", completion = "Der Tod des Boten Aph'lass hat leider nicht zu einem Ende der Rankenangriffe geführt. Ihr habt getan, was Ihr konntet, {name}. Dafür danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25915] = { id = 25915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Stärke", description = "Der dunkle Usurpator Nemesis floh hierher, als die Feuer des Hyjal verglommen. Wir sind noch nicht stark genug, um Nemesis zu besiegen, {name}, aber wir können vielleicht seine eigene Stärke gegen ihn verwenden.\n\nIch werde einen Abkömmling Tortollas mit Euch entsenden, eines der Kinder, das Ihr aus der Verderbnis des Zwielichts errettet habt.\n\nSucht in den Tiefen dieser Höhle nach einem Nemesiskristall und erlaubt der jungen Schildkröte, ihn zu untersuchen.\n\nFalls Ihr Euren Begleiter verliert, meldet Euch bei mir!", sourceObjective = "Begleitet einen Abkömmling von Tortolla zu einem Nemesiskristall. Falls Ihr Euren Begleiter verliert, meldet Euch bei Garunda Bergkuppe.", completion = "Ah, ja, ja… Die geheime Stärke von Nemesis, zugänglich hier in diesen Höhlen.\n\nWir wissen alles, was wir wissen müssen, {name}. Jetzt ist es Zeit, der Angelegenheit ein Ende zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25916] = { id = 25916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25917] = { id = 25917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Allianzsklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Allianz in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25918] = { id = 25918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Admiral Dvorek bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25919] = { id = 25919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Kapitän Taylor lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht finden Eure Waffen ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25920] = { id = 25920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Valoren verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Kapitän Taylor und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25921] = { id = 25921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Südosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten.", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Kapitän Taylor hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25922] = { id = 25922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Kapitän hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Dem Licht sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25923] = { id = 25923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Nemesis", description = "Euer Schildkrötenfreund kann diese neu gefundene Macht nutzen, um Euch beide für einen kurzen Augenblick unverwundbar zu machen. Ihr könnt Euch also in Euren \"Panzer\" verkriechen, um Nemesis' schlimmsten Zorn zu entgehen. Ruft dazu einfach dieses Totem herbei.\n\nDas ist alles, was ich für Euch tun kann. Ihr und ein Abkömmling von Tortolla müsst gemeinsam Nemesis besiegen, ein für alle Mal. Vernichtet den Usurpator!\n\nFalls Ihr Euren Schildkrötenfreund verliert, kehrt zu mir zurück.", sourceObjective = "Benutzt das Totem von Tortolla, um einem Abkömmling von Tortolla dabei zu helfen, Nemesis zu besiegen. Falls Ihr Euren Schildkrötenfreund verliert, sprecht mit Garunda Bergkuppe.", completion = "Der Usurpator ist nicht mehr!\n\nDer Schattenhammer hat davon geträumt, sich sein eigenes Pantheon von Göttern zu schaffen, die über Land, Meer und Luft herrschen. Doch mit Eurer Hilfe wurden sie alle vernichtet. Wir müssen sofort Tortolla davon berichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25924] = { id = 25924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht ruft", description = "Hört zu, {race}!\n\nAn der Küste der Östlichen Königreiche ist eine neue Landmasse aufgetaucht! Eine wichtige Schlacht um die Kontrolle dieser Insel ist bereits im vollen Gange.\n\nWenn wir hier gewinnen, ist Sturmwind komplett unverteidigt!\n\nJetzt ist die Zeit, um zuzuschlagen!\n\nMeldet Euch sofort an den Docks, damit man Euch zur Schlacht bringt.\n\nAll unsere Kriegsschiffe befinden sich bereits im Kampf, also werdet Ihr ein Söldnerboot nehmen, das vom Kriegshäuptling selbst angeheuert wurde.", sourceObjective = "Fahrt mit dem Söldnerboot zur Schlacht.", completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25925] = { id = 25925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'darahs Rache", description = "Wir müssen versuchen, Kontakt zum Weitblicktal im Süden herzustellen. Unsere darnassischen Glevenwerfer stehen Euch zur Verfügung, {name}. Schlagt mit ihnen eine Schneise in die anrückenden Hordenstreitkräfte und räumt einen Weg ins Weitblicktal frei.\n\nHoffentlich ist es noch nicht zu spät, um das Tal zu retten. Sollte das Weitblicktal unversehrt sein, dann sucht dort nach Hierophant Malyk und informiert ihn über unsere Lage.", sourceObjective = "Tötet 20 Soldaten der Horde und zerstört 3 Verwüster von Krom'gar im Kriegsnarbental.", completion = "Wir haben die Explosion der Bombe beobachtet. Was für eine furchtbare Zerstörung... Das Weitblicktal ist unversehrt, was immer das auch nutzen mag. Allerdings wissen wir nicht, wohin wir fliehen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25926] = { id = 25926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modernder Hass", description = "Die Morastbestien im Westen sind nicht meine Brüder... sie sind Symptome der gestörten Erde, eine modernde, Gestalt gewordene Verderbtheit.\n\nIhr würdet es nicht verstehen... sie nehmen die Gestalt meines Volkes an, sind jedoch mit verrottenden Sporen durchsetzt. Sie vertreiben das blühende Leben aus dem Sumpf. Sie nehmen alles und lassen nur Verderbtheit zurück. Nichts bleibt zurück! Nichts!\n\nTröstet mich, {race}. Tötet die Morastbestien und reinigt das Land. Vielleicht bringt mir das Frieden.", sourceObjective = "Tötet 10 modernde Morastbestien.", completion = "Ahhh... ja. Der Sumpf leidet weniger als zuvor.\n\nEs gibt jedoch noch mehr Bedrohungen. Sie lauern. Ich kann sie sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25927] = { id = 25927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Bedrohung", description = "Die Flammen bedrohen mich schon seit langer Zeit... zu langer Zeit... aber es sind keine kleinen mehr, nicht mehr nur noch Funken...\n\nDie Felder brennen! Die Hügel und Hochlande schreien, {race}, sie schreien. Die Elementare, die hierher gebracht wurden, lassen nur Tod zurück.\n\nDas darf nicht so weitergehen. Haltet sie auf. HALTET SIE AUF! Vernichtet die Flammenboten...", sourceObjective = "Tötet 8 zügellose Feuerelementare.", completion = "Ja... die Flammen vergehen. Nun herrscht Friede. Das Land findet Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25928] = { id = 25928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Triumph", description = "Ich werde die Abkömmlinge von Tortolla hier heraus begleiten und dieses verfluchte Portal versiegeln.\n\nIch überlasse es Euch, Tortolla von unserem Sieg zu berichten. Tretet einfach wieder durch das Flammentor. Der Ahn wird begeistert sein!", sourceObjective = "Geht erneut durch das Flammentor und kehrt zu Tortolla auf der Verbrannten Ebene auf dem Hyjal zurück.", completion = "Ihr wart in den Feuerlanden?\n\nNemesis ist tot?\n\nAlso ist es vorbei.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25929] = { id = 25929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetauglich", description = "Grüße, {class}. Ich bin Erunak, einer der Überlebenden dieses Unglücks.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga durchstreifen die Gewässer und greifen alles an, was noch am Leben ist.\n\nIhr seid an die hiesigen Bedingungen noch nicht ausreichend angepasst, um zu überleben, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Euch dabei helfen wird, Euch an die neue Umgebung zu gewöhnen.", sourceObjective = "Sammelt 3 Salzwasserseesterne und ein Tritonshorn am Meeresgrund im Verhängnis der Legion.", progress = "Konntet Ihr alle Gegenstände finden, die ich brauche, {race}?", completion = "Bitteschön, {class}. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25930] = { id = 25930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talstürmer", description = "Man hat mir erzählt, dass das Verbrannte Tal vor dem großen Umbruch eine Mulde war, ohne Zugang zum Meer. Doch wenn man nun nach Süden blickt, wird deutlich, dass das Verbrannte Tal längst kein Tal mehr ist, sondern ein Gebiet mit großer vulkanischer Aktivität.\n\nSalsbury hat ein Gerät konstruiert, mit dem wir den Vulkan erklimmen können. Benutzt es, um zum Gipfel zu gelangen. Findet heraus, was dort vorgeht.\n\nIch werde mit dem Gnomcordergerät, das Salsbury mir freundlicherweise geschenkt hat, in Kontakt bleiben.", sourceObjective = "Erklimmt mit Salsburys Raketenpack den Vulkan im Verbrannten Tal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25931] = { id = 25931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Seldarria", description = "<Der Gnomcorder summt.>\n\nSeid sehr vorsichtig, {name}. Weckt bloß nicht den schwarzen Drachen auf.\n\nSeht Euch um. Wenn dies ein Nest ist, dann sollte es in der Nähe schwarze Dracheneier geben. Sucht das Gebiet nach Eiern ab und zerstört alle, die Ihr seht.\n\nKehrt zu mir zurück, wenn Ihr Seldarrias Eier gefunden und zerstört habt.\n\nMöge Goldrinn über Euch wachen.", sourceObjective = "Zerstört 5 Eier von Seldarria.", completion = "Ein durchschlagender Erfolg! Es ist vielleicht nur ein kleiner Sieg über die Brut von Todesschwinge, aber wenigstens ein Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[25932] = { id = 25932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Nacht ein Überfall", description = "Die Berichte, die ich Hauptmann Tharran schicke, spiegeln das Ausmaß des Ärgers, den uns die Frostmähnen bereiten, nicht richtig wider. Euer Angriff auf das Dorf hat etwas Druck von uns genommen. Die Überfälle finden immer noch häufig statt, aber es gibt nicht mehr so viele Trolle wie früher.\n\nTrotzdem sind meine Männer erschöpft. Die Moral sinkt. Würdet Ihr uns im Kampf gegen die Frostmähnenräuber unterstützen? Sie können jederzeit auftauchen.", sourceObjective = "Helft Unteroffizier Flinthammer und seinen Gebirgsjägern, das Gehöft Bernruh gegen die Frostmähnenräuber zu verteidigen.", completion = "Dank Eurer Hilfe ist es uns gelungen, die Räuber deutlich zu schwächen. Solche Verluste haben sie seit Beginn der Überfälle nicht mehr erlitten. Wir müssen diesen Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25933] = { id = 25933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Steinbruch", description = "Ich möchte Euch noch einmal für Eure Hilfe danken, {name}.\n\nMein Cousin hat früher in den Minen unter dem Steinbruch Gol'Bolar gearbeitet, aber seit die Troggs dort eingedrungen sind und die Kontrolle übernommen haben, geht das nicht mehr. Der Steinbruch und sein Lager liegen südöstlich des Gehöfts. Würdet Ihr Euch dort bei dem Großknecht melden und herausfinden, ob man etwas unternehmen kann?", sourceObjective = "Sprecht mit Großknecht Steinbraue im Steinbruch Gol'Bolar.", completion = "Unteroffizier Flinthammer? Der Name sagt mir nichts, aber einer der Minenarbeiter heißt Flinthammer. Er gehört zu den Glücklichen, die aus der Mine fliehen konnten, aber die meisten anderen sind dort unten eingeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25934] = { id = 25934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltneuheit: Gnomgen", description = "Guten Tag, Bürger, ich möchte mich Euch vorstellen. Ich bin Salsbury, bald der welterste Gnomgen. Malyk hat mir versichert, dass er mir nach Beendigung meiner Arbeit das Geschenk des Worgen machen wird.\n\nSo, da wir uns jetzt kennen, möchte ich eine Bitte äußern!\n\nSüdlich von hier, im Verbrannten Tal, treiben neu erschaffene Feuerelementare ihr Unwesen. Ich brauche dringend ein seltenes flammendes Herz des Feuers von einem der Unholde. Beschafft es für mich, dann komme ich dem Leben eines Gnomgen einen Schritt näher!", sourceObjective = "Beschafft 1 flammendes Herz des Feuers.", progress = "Habt Ihr das flammende Herz des Feuers bekommen?", completion = "Hervorragend. Damit kann ich meine letzte Aufgabe beenden und hoffentlich die Wolfsform bekommen!\n\n<Salsbury heult.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25935] = { id = 25935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Welpen", description = "Ah, ein Neuankömmling! Gut, dass Ihr hier seid <Junge/Schwester>! Die Welpen sind hungrig, aber uns ist die Nahrung ausgegangen.\n\nZum Glück lieben sie Drachenfleisch, was es in rauen Mengen im Verbrannten Teil südlich von hier gibt.\n\nSeid ein <guter Junge/gutes Mädchen> und besorgt mir ein paar Pfund Schwarzdrachenwelpenfilet.", sourceObjective = "Beschafft 6 Schwarzdrachenwelpenfilets.", progress = "Beeilt Euch, {name}, die Welpen sind hungrig!", completion = "Hervorragend. Die Hunde werden gut zu fressen bekommen und unseren Außenposten wochenlang verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25936] = { id = 25936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ich Euch, so Ihr ihnen", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", sourceObjective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", progress = "Konntet Ihr die Krieger retten, {race}?\n\nOhne ihre Hilfe sind wir verloren…", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Krieger wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25937] = { id = 25937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unermessliche Reichtümer", description = "In dem Steinbruch wurde nicht nur geschürft. Ich leitete ein Ausgrabungsteam der Forscherliga. Wir suchten nach wertvollen alten Artefakten.\n\nMir gelang die Flucht, aber meine Kollegen hielten sich tiefer in der Mine auf und überlebten den ersten Angriff der Troggs nicht.\n\nSie waren sehr stolz auf ihre Arbeit und riskierten ihr Leben, um mehr über unsere Geschichte herauszufinden. Wenn Ihr in die Minen geht, dann nehmt diese Spitzhacke mit. Vielleicht findet Ihr ja etwas in den Stollen, die von den Ausgräbern begonnen wurden.", sourceObjective = "Bergt 8 gefrorene Artefakte aus der Mine des Steinbruchs Gol'Bolar.", progress = "Habt Ihr dort unten Artefakte gefunden?", completion = "Ich danke Euch für die Bergung dieser Artefakte. Ich werde dafür sorgen, dass sie im Museum von Eisenschmiede ausgestellt werden, zusammen mit der Geschichte derer, die bei ihrer Bergung ums Leben kamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25938] = { id = 25938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Desolace", description = "Ich habe eine verstörende Nachricht aus Nijelspitze in Desolace erhalten. Der große Umbruch hat anscheinend neue Probleme mit sich gebracht, auf die sie nicht vorbereitet waren. Mehr weiß ich nicht.\n\nMeldet Euch bei Offizierin Jankie in Desolace. Sie wird Euch den Weg nach Nijelspitze weisen.\n\nViel Glück, {name}.", sourceObjective = "Meldet Euch bei Offizierin Jankie in Tethris Aran in Desolace.", completion = "Halt, Fremder!", sourceObjectiveStatus = "unverified-source-field" }
quests[25939] = { id = 25939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerteufel", description = "Die Elementare, die auf dem Hügel der Düsterschmiede randalieren, stecken das Land unter sich in Brand. In einem Sumpf wie diesem findet das Feuer im tiefen Moos und Torf ausreichend Nahrung.\n\nLöscht die Feuer, bevor sie sich ausbreiten. Nehmt diese Blume... sie wurde mit dem Regen der Natur gesegnet und wird Euch ermöglichen, die Feuer zu löschen.\n\nIhre Blüten könnten sich außerdem als nützlich gegen die Elementare erweisen.", sourceObjective = "Löscht 7 Moorfeuer mit der gesegneten Flutlilie.", completion = "Ihr habt nicht nur das Land vor weiterem Leid bewahrt, sondern uns auch geholfen, den Sumpfwächter zu besänftigen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25940] = { id = 25940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Gefecht am Rauschenden Hain", description = "Möglicherweise habe wir jetzt eine Chance, die Flammen dank Eurer Arbeit in dem Inferno zu besiegen.\n\nDennoch sind weitere Wildtiere bedroht. Bewahrer Taldros rannte Richtung Norden durch die Flammen zum Rauschenden Hain.\n\nSeht, ob Ihr ihm helfen könnt!", sourceObjective = "Meldet Euch bei Bewahrer Taldros im Rauschenden Hain auf dem Hyjal.", completion = "Die Flammen verschlingen den Wald!", sourceObjectiveStatus = "unverified-source-field" }
quests[25941] = { id = 25941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rast für die Erschöpften", description = "Ihr habt Eure Aufgabe gut gemacht, {race}, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", sourceObjective = "Sprecht mit Legionär Nazgrim.", completion = "Ich verstehe, {race}.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25942] = { id = 25942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "Viele gute Krieger mussten heute ihr Leben lassen.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", sourceObjective = "Tötet 8 Räuber des Zin'jatar im Verhängnis der Legion.", progress = "Habt Ihr diesem schuppigen Abschaum einen Grund zum Nachdenken gegeben, {class}?", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um uns die nötige Zeit zu verschaffen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25943] = { id = 25943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege gehen durch den Magen", description = "Wenn ich diese Orcs für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Mampf, kein Kampf.\n\nDiese Krieger sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass die Naga angreifen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", sourceObjective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", progress = "Habt Ihr Nahrung für die Truppen, {race}?", completion = "Ein leckerer Happen.\n\nBald sind wir wieder kampfbereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25944] = { id = 25944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Horde alte Kleider", description = "In unserem Kampf gegen das Ertrinken waren meine Orcs und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich glaube ihm.\n\nWenn wir siegen wollen, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen.\n\nEs sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks hier und im Norden liegen.\n\nSchnell, {race}. Der Feind könnte jeden Moment eintreffen.", sourceObjective = "Sammelt 5 Äxte von Orgrimmar, 5 Brustplatten von Orgrimmar und 5 Helme von Orgrimmar am Meeresboden oder von Strauchdieben der Gilblin im Verhängnis der Legion.", progress = "Konntet Ihr unsere Ausrüstung zusammensammeln, {race}?", completion = "Das habt Ihr gut gemacht, {race}.\n\nUnsere Überlebenschancen steigen stetig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25945] = { id = 25945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben hier nur eine Aufgabe, vielleicht auch zwei...", description = "Ihr seid jetzt in Höllschreis Armee, {name}, und in Höllschreis Armee treten wir anderen in den Hintern und sind verdammt nachtragend. Die Zeiten, in denen Leute auf den Straßen Orgrimmars verhungerten, während wir Verträge mit den Elfen schlossen, sind vorbei. Wir holen uns jetzt, was wir brauchen. Kalimdor gehört der Horde!\n\nDie Allianz versucht bei jeder Gelegenheit, unsere Expansion aufzuhalten. Diesen Schweinslutschern gehört bereits ein Großteil der Östlichen Königreiche, aber das reicht ihnen nicht!\n\nOberanführer Krom'gar will mehr Truppen ins Steinkrallengebirge verlegen. Schließt Euch der Karawane westlich von hier an. Geht!", sourceObjective = "Reist mit dem Wagen von Krom'gar zum Bruch im Steinkrallengebirge.", completion = "Solange Ihr im Steinkrallengebirge seid und als ein Soldat Krom'gars kämpft, werdet Ihr Uniform tragen! Ist das klar? HÖRT Ihr mich, Grunzer? Wenn ich Euch ohne Höllschreis geliebten Waffenrock sehe, werde ich Euch so heftig in den Hintern treten, dass Ihr Schnürsenkel ausspuckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25946] = { id = 25946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ScHELMenstück", description = "<Dieser Helm und das passende Zubehör sind mit dem Siegel von Sturmwind gekennzeichnet. Er stammt ohne Zweifel von einem Allianzschiff, dass ein ähnliches Schicksal wie Euer Schiff erlitten hat.>\n\n<Wenn Ihr den Helm genauer betrachtet, fällt Euch auf, dass er viel zu gut verarbeitet und stabil ist, um zu einer normalen Tauchausrüstung zu gehören. Vielleicht weiß Nazgrim ja, was es damit auf sich hat...>", sourceObjective = "Bringt die Kampfschwimmerausrüstung der Allianz zu Legionär Nazgrim in der \"Ewiger Kreislauf\".\n\nBereitgestellter Gegenstand:", completion = "Blut und Donner!\n\nDas ändert alles, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25947] = { id = 25947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer es findet, darf es behalten", description = "Ich erkenne diesen Helm, {race}. Es war klug von Euch, ihn mir zu bringen.\n\nDie Allianz hat eine Spezialeinheit, die für Erkundungen und Kampfeinsätze unter Wasser ausgebildet und ausgerüstet wurde.\n\nWie es scheint, haben sie in dieser Gegend weitaus mehr vor, als sich gegen unseren Angriff zu verteidigen.\n\nEs muss da unten noch mehr davon geben. Wenn Ihr sie findet, könnte sich das Blatt für unseren Vorposten schnell wenden.", sourceObjective = "Sammelt 5 Teile einer Kampfschwimmerausrüstung von Sturmwind.", progress = "Konntet Ihr weitere Teile der Allianzausrüstung finden, {name}?", completion = "Gut gemacht!\n\nJetzt sind wir so bereit wie nie, uns den Naga entgegenzustellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25948] = { id = 25948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gewartet!", description = "Es ist an der Zeit, {class}.\n\nWir sind so bereit wie es nur geht!\n\nIch werde zu den Truppen sprechen und dann schwimmen wir ins Meer, dem Schicksal entgegen.", sourceObjective = "Sprecht mit Legionär Nazgrim an Bord der \"Ewiger Kreislauf\".", completion = "Keine Zeit für Ansprachen.\n\nAuch gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[25949] = { id = 25949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut und Donner!", description = "Die Zeit ist gekommen, um uns zur Wehr zu setzen, {race}.\n\nWir werden dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass dieser Nagaabschaum es sich zweimal überlegt, bevor er sich ihm erneut nähert!\n\nFür die Horde!", sourceObjective = "Helft Legionär Nazgrim dabei, die \"Ewiger Kreislauf\" zu verteidigen.", completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[25950] = { id = 25950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <der/die> berühmte {name}, von <dem/der> alle reden? Schön, Euch kennenzulernen, Schätzelchen. Kommt, lasst mich mal ein Auge riskieren.\n\nGenug Geplauder, kommen wir zur Sache, ja? Ich will, dass Ihr für mich nach Nordwesten zu der Frontlinie der Sira'kess schwimmt und den Naga ordentlich einen vor den Latz knallt.\n\nNix Wildes. Die sind nur auf Streit aus und den sollen sie kriegen!", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Nicht schlecht, Herr Specht, {name}! Das wird den Schlangen zeigen, wo der Hammer hängt und wer hier der Boss ist!\n\nUnd jetzt zu dem versprochenen Umtrunk - lieber einen Branntwein aus Zuckerrohr oder einen guten Traubensaft?", sourceObjectiveStatus = "unverified-source-field" }
quests[25951] = { id = 25951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlussurteil", description = "Geht zur Brücke im Osten, schnell. Lady Naz'jar und der Tiefenlord sollten sich dort mit den verbleibenden Streitmächten aufhalten.\n\nFolgt wie immer den Anweisungen unserer Lady. Haltet die Brücke, bis wir das Ritual beenden können.\n\nSobald unsere Verbündeten eintreffen, sind die Kvaldir dem Untergang geweiht.", sourceObjective = "Haltet die Brücke auf der Terrasse von Quel'Dormir, bis Lady Sira'kess' Verbündete eintreffen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Bleibt an unserer Seite, Kriegsmaid. Am heutigen Tage werden wir nicht fallen.", completion = "Ich könnte mir keine fähigere Kriegsmaid wünschen als Euch. Ihr habt Euch heute große Ehre verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25952] = { id = 25952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", sourceObjective = "Tötet 10 Patrouillen der Azsh'ir.", completion = "Ausgezeichnete Arbeit, {class}.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25953] = { id = 25953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", sourceObjective = "Zerstört 8 Überwacher der Azsh'ir.", completion = "Gut gemacht, {name}. Und genau rechtzeitig. Der Hauptmann hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25954] = { id = 25954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vergangenheit", description = "Hört mal... {name}, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nZu der Zeit als Azshara regierte, war dies eine königliche Stadt der Elfen. Tief in dieser Stadt liegen die Schlüssel zu lange verschollenem Wissen und Artefakten von unermesslichem historischen Wert. Bitte, haltet doch nach interessanten Gegenständen Ausschau, wenn Ihr ohnehin schon in der Stadt seid.", sourceObjective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der Großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25955] = { id = 25955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Standort", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", sourceObjective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, {class}.\n\nEs klingt so, als ob das Gebäude nördlich der Gärten einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25956] = { id = 25956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zur Ruhestatt der Legion.", progress = "Ja, {class}?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25957] = { id = 25957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Hauptmann es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Hauptmann und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25958] = { id = 25958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Hauptmann hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er trifft dort Vorbereitungen für eine Art Angriff auf die Naga.\n\nIhr solltet sofort zu ihm gehen und ihn über das Ausmaß dessen, was Ihr beobachtet habt, unterrichten. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferdchen. Es kennt den Weg.", sourceObjective = "Sprecht mit Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir.\n\nBenutzt das Seepferdchen von Wellensprecherin Tulra, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25959] = { id = 25959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden, unter der Terrasse, ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25960] = { id = 25960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Hauptmann gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Bringt ihnen mehr Armbrustbolzen, um uns etwas Zeit zu verschaffen.", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Horde auf den Felsvorsprüngen um das nördliche Ende der Gärten von Quel'Dormir.", completion = "Ihr seid wahrscheinlich der zuverlässigste {race}, den ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25962] = { id = 25962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Ich war schon überall. Habe alle möglichen Dinge in die Luft gejagt. Ich dachte, ich hätte vielleicht Probleme damit, den neusten Entwicklungen zu folgen. Ihr wisst schon, wegen dem Wasser und so, aber es ist alles nur eine Frage der Inspiration.\n\nIch habe etwas gefunden, das explosiv genug ist, um Bomben daraus zu bauen. Unter der Terrasse im Südwesten hängen ein paar Tangblasen herab. Normalerweise speichert Tang Gas, das ihn zum schweben bringt, doch dieses schwere Gas ist ganz anders. Es bringt ihn dazu, hängen zu bleiben. Außerdem eignet es sich perfekt für Explosionen.\n\nKönnt Ihr mir etwas davon sammeln?", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25963] = { id = 25963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der südlichen zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Fiasco Siedefeix, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", completion = "Ihr habt Euch da oben großartig geschlagen, Soldat! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25964] = { id = 25964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25965] = { id = 25965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Hauptmann zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben.\n\nEine ihrer größten Gruppen befand sich im nordwestlichen Teil dieser runden Terrasse und die andere ein wenig weiter im Norden, in dem kleinen Tunnel, ebenfalls auf der mittleren Ebene der Ruinen.\n\nInterressiert an ein wenig Arbeit als Kundschafter?", sourceObjective = "Späht den Rand der runden Terrasse im Nordwesten und den Tunnel unter der Haupttreppe im Norden aus. Beides befindet sich auf der Terrasse von Nar'shola, in der mittleren Ebene der Ruinen.", progress = "Wisst Ihr schon etwas Neues… zu ihren Zahlen?", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25966] = { id = 25966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25967] = { id = 25967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt das Seepferdchen von Wellensprecherin Tulra, um zu Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Schön, Euch in einem Stück zu sehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25968] = { id = 25968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Toldrek und Fiasco sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Wir werden hier nicht viel länger aushalten. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Fiasco Siedefeix auf dem Biel'arangrat.", completion = "Schaut Euch an, Ihr seid ein echter Held des Meeres! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Ihr müsst stolz auf Euch sein!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25969] = { id = 25969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Fiasco kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Gilblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Gilblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25970] = { id = 25970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Es ist nicht weit bis zur Oberfläche. Eigentlich alles kein Problem. Doch es ist nicht leicht, Ausrüstung nach da oben zu bringen. Sie ist einfach zu schwer.\n\nAlle Schiffe in der Flotte der Horde sind mit einer Überlebensausrüstung ausgestattet. Ich hatte einen Ballon aus so einer Überlebensausrüstung, aber er musste sich leider den Widrigkeiten geschlagen geben. Ich brauche noch eine Überlebensausrüstung.\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren, die Überlebensausrüstung nicht mitzunehmen. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Horde.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25971] = { id = 25971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Seile und Bomben, das ist alles, was sie enthalten sollten. Der Rest des Krams ist einfach nur Platzverschwendung.\n\nBis auf den Ballon vielleicht. Der kommt uns jetzt gerade gelegen.\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Seile sind nicht optional!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25972] = { id = 25972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Gut gemacht.\n\nToldrek ist bereits nach oben geschwommen, um ihn zu packen. Er macht sich Sorgen um die Strömung und all so was. Er meinte aber, er würde Euch die Ehre überlassen. Netter Kerl - Keine Ahnung, wie er am Leben bleibt.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Horde Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Hordenschiffe.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25973] = { id = 25973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Legionär Nazgrim an der Ruhestatt der Legion zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ihr habt hier unten Euren Wert mehr als deutlich bewiesen. In der Horde ist ein Ehrenplatz für Euch sicher.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25974] = { id = 25974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <dieser/diese> {name}, von <dem/der> alle sprechen? Schön, Euch endlich zu treffen.\n\nNun, genug der Worte. Lasst uns zur Sache kommen. Ihr müsst für mich nach Nordwesten zur Frontlinie der Sira'kess schwimmen und schnell diese Naga erledigen.\n\nNichts Aufregendes. Sie sind auf einen Kampf aus und wir werden ihnen einen bieten. Mit 'wir' meine ich natürlich Euch.", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Sehr gut, {name}! Das wird diesen Naga zeigen, wer hier die Hosen anhat!\n\nAlso, zu unserem Schlückchen. Was mögt Ihr lieber? Rum oder Wein?", sourceObjectiveStatus = "unverified-source-field" }
quests[25975] = { id = 25975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Wir haben unsere ersehnte Verstärkung, aber immer noch keine Ahnung, wie wir sie bezahlen sollen. Und diese Art von Hilfe ist nicht ganz billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für unsere Zwecke zurückzustehlen.", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das sollte vorerst reichen. Wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25976] = { id = 25976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Blut und Donner! Wir haben unsere ersehnte Verstärkung, aber wir müssen sie leider auch bezahlen. Das wird sicher nicht billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für die Horde zurückzustehlen.\n\nHöllschreis Augen ruhen auf Euch, {name}!", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das ist ganz schön viel. Und wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25977] = { id = 25977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Schlangen sind hinter unserer Armee her. Geht nach Nordwesten zum Tiefenflossengrat und steckt dem Futzi, den sie ihren Boss nennen, ein bisschen Holz zwischen die Rippen.\n\nWenn sie das sehen, werden sie Angst bekommen und abhauen mit dem Schwanz zwischen den Bei... ach nee, Beine haben sie ja gar keine.", sourceObjective = "Rammt die Standarte der Allianz in Tiefenrufer Azrajars Leichnam.", completion = "Saubere Arbeit! \"O'zapft is der General!\", würde ich mal sagen.\n\n<Der Leutnant schüttelt mit dem Kopf und grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25978] = { id = 25978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Eis eingeschlossen", description = "Khurgorn sagt, der Kataklysmus habe das Gleichgewicht der Elemente auf der ganzen Welt erschüttert. Der Helmsbettsee im Süden war einmal wunderschön und ruhig, doch nun wimmelt es dort von wütenden Wasserelementaren. Als sie begannen, den See zu verlassen, schickte ich Truppen dorthin, um sie abzulenken, aber die meisten wurden in Eisblöcken eingefroren.\n\nWenn wir sie befreien können, werden sie sich wahrscheinlich erholen. Ich kann niemanden für eine zweite Expedition zum See entbehren. Würdet Ihr es versuchen?", sourceObjective = "Öffnet sechs eisige Gräber, um die gefrorenen Gebirgsjäger am Helmsbettsee zu befreien.", progress = "Konntet Ihr den Gebirgsjägern helfen?", completion = "Ihr habt es geschafft! Die Gebirgsjäger kehren ins Lager zurück. Unsere Sanitäter werden viel zu tun haben. Wir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25979] = { id = 25979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glättet die Wogen", description = "Die Elemente sind aufgewühlt, {class}. Der Kataklysmus hat die schlafenden Wassergeister im Helmsbettsee südlich von hier geweckt. Sie sind wütend, verwirrt und nicht gewillt, sich meine Bitten anzuhören.\n\nIch habe alles versucht, um sie zu beruhigen und davon zu überzeugen, die Gebirgsjäger des Unteroffiziers nicht mehr anzugreifen.\n\nIch sage das nur ungern, aber uns bleibt keine andere Wahl -- wir müssen die Elementare töten.", sourceObjective = "Tötet 6 Woger des Helmbettsees am Helmbettsee.", completion = "Es fällt mir nicht leicht, Gewalt gegen die Elemente anzuwenden, deren Macht ich benutze, aber manchmal gibt es keinen anderen Weg. Wir sind zuerst den Bewohnern Dun Moroghs verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25980] = { id = 25980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Naga sind hinter unseren Streitmächten her. Ihr müsst für mich zurück nach Nordwesten zum Tiefenflossengrat gehen und unsere Standarte in ihren General, Tiefenrufer Azrajar stechen.\n\nSie werden vor Angst davon schwimmen, mit dem Schwanz zwischen den… äh. Na ja, Beine haben sie ja wohl nicht, oder?", sourceObjective = "Rammt die Standarte der Horde in Tiefenrufer Azrajars Leichnam.", completion = "Ihr habt ihn also richtig durchbohrt? Das hätte ich ja zu gerne gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25981] = { id = 25981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Auch eine Art, an Sklaven zu kommen.\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen?", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Wie viele habt Ihr?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Stinken nur ganz schön.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25982] = { id = 25982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Wir müssen verhindern, dass sie hierher kommen!\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen? Bevorzugt tote Exemplare, schätze ich.", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Was stinkt hier so?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Eigentlich. Irgendwie sind sie fast schon niedlich.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25983] = { id = 25983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "Wir müssen diese Informationen zu Kapitän Taylor am Kap bringen. Er befindet sich im Nordwesten mit Erunak Steinsprecher und den Mitgliedern des Irdenen Rings.", sourceObjective = "Sprecht mit Kapitän Taylor am Kap in Vashj'ir.", completion = "Das sind verstörende Neuigkeiten, doch ich glaube, dass unsere Freunde vom Irdenen Ring einen Plan haben.\n\nUnd jetzt, da Ihr hier seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[25984] = { id = 25984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "{name}, ich möchte, dass Ihr diese Informationen zu Legionär Nazgrim am Kap bringt. Er befindet sich im Nordwesten mit Erunak Steinsprecher und diesen Leuten vom Irdenen Ring.", sourceObjective = "Sprecht mit Legionär Nazgrim am Kap in Vashj'ir.", completion = "Ich würde meinen Ohren nicht trauen, wenn nicht Ihr der Überbringer dessen wärt, was dieser lästige Goblin zu sagen hat. Das ist in der Tat beunruhigend, aber ich glaube, dass unsere Freunde vom Irdenen Ring einige Ideen haben.\n\nUnd wo Ihr nun hier seid…", sourceObjectiveStatus = "unverified-source-field" }
quests[25985] = { id = 25985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen über dem Hyjal", description = "{name}, ist es wahr, dass Ihr versuchen werdet, mit den Ahnen zu sprechen?\n\nSüdwestlich von hier befindet sich der Schrein von Aviana, der Mutter aller fliegenden Lebewesen. Dort lebt meine Lieblingslehrerin, Choluna. Ich habe noch nie jemanden kennengelernt, der so eins mit den Geistern dieser Welt war. Ihr könntet viel von ihr lernen!\n\nWegen der kürzlichen Angriffe ist der Schrein von der Außenwelt abgeschnitten. Aber aus der Luft könnt Ihr ganz einfach dorthin gelangen. Haltet nach dem größten Baum auf dem Hyjal Ausschau. Viel Glück!", sourceObjective = "Findet Choluna am Schrein von Aviana auf dem Hyjal.", completion = "Oh, Tiala schickt Euch? Was für eine herausragende Schülerin. Sie wird noch Großartiges erreichen.\n\nObwohl ich in Euch sogar noch mehr Potenzial spüre.\n\nBitte, bleibt doch eine Weile bei unserem Schrein. Es gibt viel zu tun, aber mit einem beunruhigten Gemüt lässt es sich kaum bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25986] = { id = 25986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am See", description = "Ihr wart eine große Hilfe bei der Sicherung der Minen und der Rettung der gefangenen Minenarbeiter.\n\nEs wird den Senat freuen, dass Ihr und Hauptmann Tharrans Gebirgsjäger Fortschritte bei der Sicherung Dun Moroghs gemacht habt.\n\nMich besorgt allerdings, dass ich keine Berichte von Unteroffizier Bahrum und seiner Abteilung erhalten habe. Sie wurden nach Osten geschickt, auf die Straße, die zum Helmsbettsee führt. Dort sollten sie einen kleinen Außenposten errichten. Würdet Ihr zu Bahrums Posten reisen und nach dem Unteroffizier sehen?", sourceObjective = "Sprecht mit Unteroffizier Bahrum an Bahrums Posten.", completion = "Gut, dass der Senator nicht allein hierhergekommen ist. Es ist gefährlich hier. Wir werden all die Hilfe brauchen, die wir kriegen können, um die Lage unter Kontrolle zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25987] = { id = 25987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "He, {name}! Ich habe eine tolle Idee für eine Verkleidung. Nehmt einen dieser gnadenlosen Wasauchimmers und setzt ihn Euch auf den Kopf.\n\nWas kann dabei schon schiefgehen?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Was ist passiert? Das Ding war wohl nicht ganz tot! Vielleicht sollte ich einfach bei den mechanischen Dingen bleiben.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will sie keinesfalls in meiner Nähe haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25988] = { id = 25988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "Ich habe eine tolle Idee für eine Verkleidung, aber ich brauche Eure Hilfe dabei, {name}. Nehmt einen dieser gnadenlosen Leichname und setzt ihn Euch auf den Kopf.\n\nIch weiß, ich weiß, aber es ist tot. Was kann dabei schon schiefgehen, außer dass Ihr ein, zwei Tage übel riecht?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Mein Fehler. Ich heiße nicht umsonst \"Fiasco\". Ich hätte wissen sollen, dass es nicht ganz tot ist, als es gezuckt hat.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will nicht, dass sie hier alles vollstinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25989] = { id = 25989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25990] = { id = 25990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25991] = { id = 25991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Hordesklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Horde in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25992] = { id = 25992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Hauptmann Übeldorn bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25993] = { id = 25993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Legionär Nazgrim lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht findet Euer Schwert ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25994] = { id = 25994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Tulra verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Legionär Nazgrim und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25995] = { id = 25995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Nordosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten. Höllschreis Augen ruhen auf Euch!", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Legionär Nazgrim hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25996] = { id = 25996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Legionär hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Höllschrei sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25997] = { id = 25997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimtücke der Dunkeleisenzwerge", description = "Eine Gruppe Dunkeleisenspione hat Eisenbands Truppenlager im Süden, hinter dem Helmsbettsee übernommen. Die Gebirgsjäger wären normalerweise in der Lage, sie aus Dun Morogh herauszuhalten, aber es herrscht gerade Chaos.\n\nDie Dunkeleisenzwerge wären Narren, wenn sie das nicht zu ihrem Vorteil nutzen würden. Wir müssen herausfinden, was sie planen und sie aufhalten, bevor sie Schaden anrichten.\n\nKönntet Ihr versuchen herauszufinden, was sie in Eisenbands Truppenlager machen?", sourceObjective = "Tötet 5 Spione der Dunkeleisenzwerge und erbeutet die Angriffspläne der Dunkeleisenzwerge von Hauptmann Beld in Eisenbands Truppenlager.", progress = "Was haben die Dunkeleisenzwerge vor?", completion = "Ich habe mir schon gedacht, dass sie nicht wegen der Aussicht hier sind.\n\n<Der Unteroffizier betrachtet die Pläne, die Ihr erbeutet habt. Seine Augen weiten sich.>\n\nDas ist ernster als befürchtet! Dies ist nicht nur ein Überfall. Die Dunkeleisenzwerge wollen die Verteidigungsbollwerke von Eisenschmiede lahmlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25998] = { id = 25998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Flugplatz", description = "Laut der Pläne, die Ihr erbeutet habt, planen die Dunkeleisenzwerge einen großangelegten Angriff auf den Flugplatz von Eisenschmiede! Der Rat hat einen Großteil unserer Streitkräfte nach Dun Morogh verlegt. Sie sollen sich dort um die Instabilität, die durch den Kataklysmus entstanden ist, kümmern. Die Verteidigungslinien des Flugplatzes sind geschwächt.\n\nWir müssen Euch so schnell wie möglich zum Flugplatz bringen. Nehmt die Straße zurück nach Westen, in Richtung des Steinbruchs Gol'Bolar und findet Mathel Rostzange. Er sollte eine Flugmaschine für Euch haben. Geht!", sourceObjective = "Steigt in Mathels Flugmaschine im Steinbruch Gol'Bolar.", completion = "Zum Glück seid Ihr hier, {name}. Der Flugplatz wird von Dunkeleisenzwergen angegriffen. Wir halten nicht mehr lange durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25999] = { id = 25999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schritt für Schritt", description = "Den schmutzigen, nichtsnutzigen Nachtelfen ist es gelungen, unser ganzes Minenfeld auf dem Steinkrallenpass zu entschärfen. Jemand muss dorthin zurückgehen und die Minen wieder scharf machen! Diese Aufgabe ist perfekt für einen wertlosen Grunzer wie Euch geeignet, {name}. Hoffentlich jagt Ihr Euch dabei nicht selbst in die Luft.\n\nUnsere \"Elfentöter\" liegen überall auf dem Steinkrallenpass, unmittelbar nördlich von hier. Nehmt diesen Schraubenschlüssel und macht Euch an die Arbeit, Made.", sourceObjective = "Macht 8 Krom'gar \"Elfentöter\" scharf.", progress = "Was habt Ihr zu melden, Grunzer?", completion = "<Saurboz mustert Euch.>\n\nIhr habt noch alle Gliedmaßen. Das gab's noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26000] = { id = 26000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit Gurrok in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[26001] = { id = 26001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Sprengenieur", description = "Ihr seid wohl doch nicht völlig nutzlos. Vielleicht bewältigt Ihr sogar eine etwas wichtigere Aufgabe.\n\nVor rund zwei Tagen habe ich Sprengenieur Fusselpfiff zur Scherwindmine geschickt. Er sollte sich dort davon überzeugen, dass alles mit der Bombe nach Plan läuft und sich dann wieder hier melden. Zwei Tage und nichts...\n\nBegebt Euch in den Wald südlich von hier und findet ihn. Wenn er Glück hat, ist er tot.", sourceObjective = "Findet Sprengenieur Fusselpfiff.", completion = "Sprengenieur Fusselpfiff ist definitiv tot. Ist vielleicht besser so.\n\nEr scheint eine Notiz in der Hand zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26002] = { id = 26002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne der Allianz", description = "<Ihr zieht die Notiz aus Fusselpfiffs toten Fingern.>\n\nSie wissen Bescheid! Sie wissen von der Bombe. Planen Angriff auf Feste Krom'gar! Ich glaube, sie suchen mich. Werde nicht sterben wie ein Feigling. Ich werde kämpfen.\n\nIch glaube, da kommen sie! Ihre Anführerin ist eine Hochelfenjägerin namens Davinia. Sie sprach von den Angriffsplänen. Rächt mich, indem Ihr sie tötet und Euch die Pläne holt! Ihr Zelt steht östlich von hier, ganz in der Nähe.\n\nMöge Höllschrei über Euch wachen...", sourceObjective = "Erbeutet die Angriffspläne der Allianz von Jägerin Davinia.", progress = "Habt Ihr Fusselpfiff gefunden?", completion = "Verdammt schade... Er war ein guter Goblin.\n\n<Saurboz schüttelt seine Faust.>\n\n{name}, Ihr habt richtig gehandelt. Dank dieser Angriffspläne können wir uns vorbereiten. Ich möchte, dass Ihr die Pläne Oberanführer Krom'gar persönlich übergebt! Es sollte eine Beförderung für Euch drin sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26003] = { id = 26003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehren von den Verlorenen Inseln", description = "In den Wäldern südlich von hier lauern große Gefahren. Sie wimmeln von darnassischen Spähern - Assassinen, die aus Darnassus geschickt wurden, um uns zu töten. Vielleicht können wir den Spieß umdrehen.\n\nAls ich auf den Verlorenen Inseln festsaß, gab mir ein Goblin diese Infrarot-Hitzebrille. Mit ihr kann der Träger die Wärmesignatur bestimmter Kreaturen sehen. Nehmt die Brille und setzt sie in den Wäldern im Süden auf. Auf diese Weise werdet Ihr die Späher leicht entdecken können. Tötet so viele Ihr könnt! Für die Horde!", sourceObjective = "Tötet 12 Späher von Darnassus.", completion = "Gut gemacht, Bruder! Jetzt wissen sie, dass sie sich nicht an die Horde anschleichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26004] = { id = 26004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feste Krom'gar", description = "Feste Krom'gar ist unsere Hauptoperationsbasis im Steinkrallengebirge. Von hier aus überwacht Oberanführer Krom'gar die militärischen Aktionen der Horde in dieser Region. Krom'gar leitet die Berichte aller Ereignisse direkt an den Kriegshäuptling weiter.\n\nDie Angriffspläne, die Ihr uns gebracht habt, beschreiben einen Angriff, der bald gegen die Feste Krom'gar geführt werden soll. Nehmt die Pläne und brecht zur Feste südwestlich von hier auf. Gebt sie dem Oberanführer.\n\nLebt wohl, {name}. Höllschrei wacht wahrlich über Euch.", sourceObjective = "Bringt die Angriffspläne der Allianz zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", progress = "Was hat diese Unterbrechung zu bedeuten? Wieso steht dieser Grunzer vor Oberanführer Krom'gar?", completion = "<Ihr gebt Oberanführer Krom'gar die Pläne.>\n\nHmm. Vielleicht steckt mehr in Euch, als es den Anschein hat. Vielleicht steckt in Euch ein Unteroffizier.\n\nRichtet Euren Blick auf Krom'gar Unteroffizier {name}, Soldaten. Er hat uns vor einem feigen Angriff der Allianz gewarnt. Einen Angriff, den wir NIEDERWERFEN werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26005] = { id = 26005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Kapitän Taylor und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nHexasept hat die hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Kapitän Taylor auf der Voldrins Mut an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es geschafft! Schön Euch zu sehen, {name}.\n\nEs ist ein tolles Gefühl, dem Wasser entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Ich bin mir sicher, dass viele der Jungs nach all den Strapazen alles geben würden, um umzudrehen und nach Hause fahren zu können. Aber wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Haltet Ihr bis zum Ende durch? Ich würde es Euch nicht übel nehmen, wenn Ihr die Nase voll hättet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26006] = { id = 26006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Legionär Nazgrim und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nFiasco hat das hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Legionär Nazgrim auf der Höllenjuwel an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es also in einem Stück geschafft, {class}.\n\nEs ist ein tolles Gefühl, diesem stinkenden Pfuhl entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Macht es Euch aber nicht zu bequem. Wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Hattet Ihr genug Ruhm für einen Tag oder stürzt Ihr Euch wieder in den Kampf, um Höllschrei Stolz zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26007] = { id = 26007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Krieger stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gurrok und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26008] = { id = 26008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Krieger inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Kriegern in der Umklammerung.", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26009] = { id = 26009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchen und zerstören", description = "Die Allianz rückt auf unsere Territorien im Steinkrallengebirge vor. Die Streitkräfte von Nordwacht haben unsere Blockade im Süden durchbrochen und besetzen nun das Scherwindtal westlich von hier. Im Norden werden wir von Nachtelfensoldaten angegriffen. All das muss aufhören!\n\nBegebt Euch ins Steinkrallengebirge und vernichtet alle Allianzsoldaten, die Euren Weg kreuzen. Ihr Tod soll als Warnung dienen.\n\nDas Steinkrallengebirge gehört der Horde!", sourceObjective = "Tötet 20 beliebige Soldaten der Allianz im Steinkrallengebirge.", completion = "Es wird noch viel Blut in dieser Erde versickern, bis der Krieg vorüber ist. Blut der Allianz...", sourceObjectiveStatus = "unverified-source-field" }
quests[26010] = { id = 26010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Die Allianz wird immer unverschämter. Westlich von hier, im Scherwindtal, haben Truppen der Nordwacht ein Lager aufgeschlagen. Zweifellos bereiten sie sich auf den Angriff vor, den Ihr uns gemeldet habt, {name}. Soweit wird es nicht kommen!\n\nNehmt diesen Flammenwerfer. Den gleichen Flammenwerfer setzten meine Verbrenner ein, um unsere Feinde aus den Wäldern zu jagen. Zerstört damit die Zelte der Nordwacht. Lasst nur Asche zurück!", sourceObjective = "Zerstört 8 Zelte der Nordwacht mit Krom'gars Flammenwerfer.", completion = "Lok'tar! Allianzschweine!\n\n<Oberanführer Krom'gar spuckt auf den Boden.>\n\nGenießt Euren Sieg, er wird nicht lange währen. Euer Mut hat uns Zeit verschafft, aber mehr nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26011] = { id = 26011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feind der Horde: Marschall Paltrow", description = "Meine Späher haben die Ursache dieses neuesten Fiaskos gefunden: Marschall Paltrow. Er kommandiert das Vorauslager der Nordwacht im Scherwindtal westlich von hier. Eliminiert ihn. Damit entfernt Ihr einen wichtigen Feldkommandanten der Allianz aus der Gleichung.\n\nPaltrow muss sterben, {name}.", sourceObjective = "Tötet Marschall Paltrow.", completion = "Habt Ihr verdächtige Dokumente in Paltrows Lager gefunden? Vielleicht an seiner verwesenden Leiche? Jeder Hinweis auf die Angriffsmuster der Allianz wären bei der Schlacht ums Steinkrallengebirge von Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger im Wyrmruhtempel", description = "Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.\n\nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?", sourceObjective = "Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.", completion = "Ich danke Euch, dass Ihr Rhonins Bitte gefolgt seid, tapferer Abenteurer.\n\nLasst mich Euch mitteilen, was uns über die jüngsten Geschehnisse bekannt ist. Jede Hilfe, die Ihr zu gewähren bereit seid, wird sehr geschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Sanktum", description = "{race}, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.\n\nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.\n\nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.", sourceObjective = "Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.", completion = "Habt Dank, {class}, dafür, dass Ihr mich aus Baltharus' Klauen gerettet habt!\n\nAllerdings gibt es noch immer sehr viel zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[26014] = { id = 26014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied", description = "Stillgestanden, <Gefreiter/Gefreite> {name}! Wir chaben kleine Problem!\n\nWir chaben geschickt Humphrey und Oskar Grabungslied zur Tiefenlichtkluft im Njordwesten, aber sie sind nicht zurückgekommen. Sie sollten ausspähen Umgebung, aber wir chaben verloren jeden Kontakt zu ihnen.\n\nEure Aufgabe, <Gefreiter/Gefreite> {name}, ist zu finden unsere Genossen und, falls sie noch ljeben, sie zu mir zurückzubringen!", sourceObjective = "Meldet Euch bei Humphrey Grabungslied in der Tiefenlichtkluft in Vashj'ir.", completion = "Natürlich sind wir noch nicht zurück! Wir haben ganz schön viele Rückschläge einstecken müssen… nicht zuletzt das Ableben meines geliebten Bruders Oskar.\n\n<Humphrey schnieft laut.>\n\nEr hat den Halt verloren und ist einfach davongetrieben, der Arme! Er wollte ein paar Fische für den Kapitän fangen, stattdessen wurde er weggespült und von einem dieser... dieser riesigen Aale gefressen! Uääääh hä hä häh hääääh!", sourceObjectiveStatus = "unverified-source-field" }
quests[26015] = { id = 26015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phosphorajagd", description = "Oskars letzter Wunsch, bevor er im Rachen dieses Großaals verschwand, war, dem Käpt'n Nahrung zu bringen. Also werden wir ihm diesen Wunsch erfüllen.\n\nMein Bruder hatte einen genialen Plan. Er hat beobachtet, wie diese Murlocs mit phosphoreszierenden Antennen Fische aus dem Schilf locken. Daraufhin hat er einen Weg gefunden, ein eigenes Gerät zu bauen. Ihr braucht nur etwas, das leuchtet.\n\nTötet die Krebse und Barsche am Grund der Kluft. Sie selbst sind nicht essbar, aber ihr Phosphora ist weitaus wertvoller als ihr Fleisch.", sourceObjective = "Besorgt Euch 6 Tiefenlichtphosphora von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen genug Phosphora, um ein starkes Licht zu erschaffen. Ihr müsst heller leuchten, als diese Murlocs!", completion = "<Humphrey nimmt Euch das Phosphora ab und bringt es an einem ungewöhnlichen Gerät an.>\n\nSo. Wunderschön! Oskar wäre sehr stolz darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26016] = { id = 26016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle aus dem Basislager", description = "Paltrow, errichtet einen Stützpunkt im Scherwindtal. Ein starker Bodenangriff ist lebenswichtig für unseren Feldzug! Wenn wir Krom'gar angreifen, werden Eure Männer für das Chaos und die Verwirrung sorgen, die unsere Gnomflugmaschinen brauchen, um nahe genug für einen Bombenangriff an die Orcfestung zu kommen.\n\nDie Flugmaschinen werden die Bombe von Krom'gar zünden, während sie noch in ihrer Basis steht und damit die gesamte Festung auslöschen.\n\nNach dem Lesen verbrennen.\n\n-Truppenkommandant Valen\n\nBasislager der Nordwachtexpedition", sourceObjective = "Bringt die Befehle des Stützpunkts zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", progress = "Mehr Gnome?", completion = "Gnomflugmaschinen? Unsere Luftabwehrkanonen funktionieren noch nicht! Wir werden hilflos sein.\n\nIch brauche Zeit für einen Plan... muss nachdenken...\n\nDer Heißluftballon darf mit seiner Ladung nicht in der Feste Krom'gar bleiben. Ich muss ihn an einen anderen Ort bringen. Unsere Pläne zur Vernichtung der Scherwindfeste sind gescheitert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26017] = { id = 26017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder", description = "Bringt dieses Gerät an Eurem Kopf an und schwimmt dann durch den Tang und die Korallen am Rand der Kluft. Es sollte dort haufenweise kleine Fische geben, die Eure neue Antenne ganz unwiderstehlich finden werden.\n\nWenn wir zur Dämmerbucht zurückkehren, werden wir Berge von Fischen für alle haben!", sourceObjective = "Setzt die Phosphorafedora auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Das habt Ihr gut gemacht, {name}! Das habt Ihr richtig gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26018] = { id = 26018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht aus für die Tiefenlichter", description = "Ach, stimmt! Ich sollte ja einen Bericht erstellen! Fast hätte ich es vergessen!\n\nSieht eigentlich nach größtenteils harmlosen Wildtieren aus hier… Bis auf diese verdammten Aale. Und ein paar Murlocs. Ich schätze, der Käpt'n wird sich wohl eher für die Murlocs interessieren.\n\nFordert ein paar von ihnen zum Kampf raus und schaut, was sie so drauf haben. Soweit ich weiß jagen die großen im Tang nach Fischen und die kleinen praktizieren irgendeine Art von Magie oder so... aber mehr weiß ich auch nicht.", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "<Humphrey hört Euch zu, während Ihr von Euren Kämpfen mit den Tiefenlichtmurlocs berichtet.>\n\nHmm… Klingt nach stinknormalen Murlocs… nur unter Wasser. Das macht den Käpt'n bestimmt froh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26019] = { id = 26019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormes Aalei", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Humphrey vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Humphrey Grabungslied am Grund der Tiefenlichtkluft in Vashj'ir.", progress = "Was habt Ihr denn da, {name}?", completion = "Waaa… ein Ei? Ein AALEI?\n\n<Sogar kopfüber könnt Ihr sehen, wie es in Humphreys Kopf rattert.>\n\nWir können ganz sicher etwas damit anfangen! Macht Euch bereit, denn jetzt ist es Zeit für ein wenig altmodische Rache à la Grabungslied!", sourceObjectiveStatus = "unverified-source-field" }
quests[26020] = { id = 26020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Bombgutz", description = "Wir müssen uns auf den bevorstehenden Angriff vorbereiten. Unsere Soldaten sollen die Bombe für den Transport bereitmachen. Ihr meldet Euch bei Obersprengenieurin Bombgutz. Sie versucht, unsere Luftabwehrkanonen zu reparieren, bislang jedoch erfolglos. Stellt sicher, dass ihre Motivation für die Reparatur der Kanonen ausreicht, {name}.", sourceObjective = "Meldet Euch bei Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", completion = "Ausreichend motiviert? Was... was soll das heißen? Hört mal zu, Unteroffizier, ich habe einen eingebauten Überlebensmechanismus namens Eigeninteresse. Das heißt, es ist in meinem eigenen Interesse, NICHT ZU STERBEN. Allerdings kann ich die Kanonen nicht ohne die richtigen Materialien reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26021] = { id = 26021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied Teil 2: Der Eier-Aal-Trick-Blues", description = "Diese Aale haben meinen Bruder gefressen. Meinen Bruder, {name}! Es ist Zeit, dass ihnen jemand zeigt, wer hier der Boss ist.\n\n<Humphrey nimmt mehrere Dynamitstangen aus seiner Weste und schiebt sie durch die Außenhaut des Eis.>\n\nDiese Großaale im Süden sind zu stark, um alleine gegen sie anzutreten, aber mit diesem Ei sollten wir für Chancengleichheit sorgen können. Legt es in der Nähe dieser Biester ab und dann... Kabumm!\n\nWenn die Bombe den Aal nicht sofort tötet, sollte er zumindest dem Tod nahe sein, sodass Ihr ihm leicht ein Ende setzen könnt.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "Oskar ist am Leben? Wartet... Was habt Ihr gesagt? Ihr habt zugelassen, dass er ERNEUT DAVONGETRIEBEN WIRD?!\n\nNun… Ihr habt Euren Teil der Vereinbarung erfüllt und ich weiß zu schätzen, was Ihr getan habt, {name}.\n\nHier… nehmt das. Für mich ist es ohnehin nur Ballast, aber es scheint nicht viel zu nützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26022] = { id = 26022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Blut", description = "Seid bereit, {name}. Ihr werdet für uns das erste Blut auf diesem Land vergießen.\n\nDas Syndikat, so nennen sie sich, besteht aus feigen Menschen, die sogar ihr eigenes Volk verraten. Ihre Isolation macht sie zu einer leichten Beute.\n\nReist nach Norden, tötet alle Syndikatssöldner, die Ihr findet und erobert Nordhof im Namen der Verlassenen. Bringt mir die Blutsteinamulette, die sie tragen, als Zeichen Eurer Eroberung.", sourceObjective = "Erbeutet 10 Blutsteinamulette von Mitgliedern des Syndikats.", progress = "Ich lasse mich nicht von leeren Behauptungen beeindrucken. Könnt Ihr Eure Loyalität beweisen?", completion = "Das ist nur der Auftakt für das Massaker, das wir über dieses Land bringen werden. Alle werden Euren Namen kennen.\n\nDas habt Ihr gut gemacht, {name}. Sieg für Sylvanas!", sourceObjectiveStatus = "unverified-source-field" }
quests[26023] = { id = 26023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trollbann der Verlassenen", description = "Ich werde Euch eine Geschichte erzählen.\n\nEs gab einmal einen einfältigen Troll namens Zengu. Man befahl ihm, das Schwert Trol'kalar zu finden, die legendäre Klinge der menschlichen Trollbannlinie. Das gelang ihm. Er dachte, seine Aufgabe sei erfüllt und wollte Arathi allein verlassen. Dabei wurde er von den Menschen getötet, die das Schwert einfach wieder an sich nahmen.\n\nWir werden nicht so einfältig sein. Unsere Apotheker haben uns jemanden gebracht, der uns helfen wird, Trol'kalar wiederzubeschaffen: den Prinzen, der es einst besaß.\n\nEr wartet darauf, Euch zu führen, {name}. Sprecht mit ihm.", sourceObjective = "Sprecht mit Galen Trollbann.", completion = "Ja... Einst war ich Prinz des gefallenen Königreichs Stromgarde. Ich wurde getötet von dem, der Trol'kalar suchte.\n\nNun bereue ich mein dummes Leben. Ich diene...nur Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26024] = { id = 26024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Marez Schattenkutte", description = "Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie mit Dämonen Umgang hat. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", sourceObjective = "Bringt Marez' Kopf zu Hauptmann Nials bei der Zuflucht.", progress = "Seid gegrüßt, {class}. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Schattenkutte erledigt? Gut gemacht, {name}. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26025] = { id = 26025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verräterische Orc", description = "Ich bin mir sicher, dass eine mächtige Hexenmeisterin in den Mauern von Burg Stromgarde haust. Von Zeit zu Zeit beschwört diese Hexenmeisterin mit Hilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Anzahl. Wir müssen die Quelle ihrer Energie entfernen.\n\nFindet und tötet die Hexenmeisterin. Bringt mir das magische Objekt, das sie bei sich trägt. Dann werde ich dafür sorgen, dass es zerstört wird und dass ihre Macht nie wieder unser Land besudelt.", sourceObjective = "Erbeutet Marez Schattenkuttes beschmutzte Blutsteinkugel.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Die Hexenmeisterin muss aufgehalten werden.", completion = "Meine ruhelosen Nächte werden sich in friedlichen Schlaf verwandeln, wenn ich diese Kugel zerstört habe. Danke, {name}. Sie dient als düstere Erinnerung an die schreckliche Macht, die Dämonen über die Orcs ausübten, bevor Höllschrei sie von ihrem Fluch befreite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26026] = { id = 26026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von einer besseren Zukunft", description = "Herr Rosie ist krank, <ehrenwerter/ehrenwerte:r> {race}. Könnt Ihr ihm helfen? Ihr müsst nur seinen Hut und seine Batterien finden, dann wird es ihm wieder gut gehen. Ich würde sie selbst holen, aber ich kann Herrn Rosie nicht allein lassen!\n\nDie gemeinen Kerle der Venture Company, hinten am Wasserrad, haben seinen Hut gestohlen und seine Batterien sind irgendwo an der Scherwindklippe versteckt. Ihr werdet richtig gut nach ihnen suchen müssen!\n\nWürdet Ihr bitte Herrn Rosies Besitz zurückbringen, damit er den Fieslingen von der Allianz eine Lektion erteilen kann?", sourceObjective = "Bergt die BD-816 Kriegsmaschine, das mechanisierte Feuer, das mechanisierte Eis und die mechanisierte Luft.", progress = "Herr Rosie ist so traurig. Wir müssen ihn wieder fröhlich machen!", completion = "<Clarissa klatscht aufgeregt.>\n\nHerr Rosie, dir geht es gleich wieder gut! Hurra!\n\n<Clarissa setzt die Teile, die Ihr gefunden habt, routiniert in \"Rosie\" ein.>\n\nOh, Herr Rosie! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[26027] = { id = 26027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Unser nächster Schlag gegen die Oger wird Euch tiefer in den Osten nach Burg Stromgarde führen. Die Lebenden klammern sich weiter an diese verfallenen Ruinen. Ihre Sentimentalität ist widerwärtig!\n\nFür uns ist Burg Stromgarde nicht mehr als ein verdorbener Bau voller Oger, die auf ihr Ende warten. Reist dorthin. Tötet ihre Schamanen und ihre Lords und sorgt dafür, dass das, was bei den Ogern als Führung durchgeht, vernichtet wird.", sourceObjective = "Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste in Stromgarde.", completion = "Alles gesäubert? Gut. Wir werden uns nicht die Mühe machen, Burg Stromgarde zu besetzen. Dieses Drecksloch muss in Staub verwandelt werden.\n\nDas Land würde sich gut für eine neue Unterstadt eignen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26028] = { id = 26028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr Rosies wilder Ritt", description = "Herr Rosie braucht jetzt einen Engel, der ihm bei der Navigation hilft. Werdet Ihr dieser Engel sein, <ehrenwerter/ehrenwerte:r> {race}? Mit Eurer Hilfe können wir es bis zur Klippe schaffen und viele, viele Allianzkämpfer töten. Was meint Ihr? Och bitte, <edler/edle:c> {class}! BITTE BITTE BITTE BITTE?\n\nWenn wir genügend Allianzler umbringen, kauft Herr Krom'gar uns allen ein Eis!", sourceObjective = "Tötet 20 Gnomingenieure und 5 Gnomklopfer.", completion = "<Oberanführer Krom'gar hustet.>\n\nIch weiß - vielleicht zum ersten Mal in meinem Leben - nicht, was ich sagen soll.\n\nIch bin mir nicht einmal sicher, wo Clarissa eigentlich her kommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26029] = { id = 26029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die echte Bedrohung", description = "Or'Kalar führt die Oger hier an. Seit Jahren entgeht er seinen Schlächtern. Seine Existenz ist eine Beleidigung der Dunklen Fürstin. Mug'thol, Verräter der Verlassenen, kommandiert ihn aus der Ferne!\n\nWir tolerieren weder Oger noch Verräter im Gebiet der Verlassenen. Bringt mir den Kopf des Ogers. Dann sorge ich dafür, dass er dieses Mal richtig verbrannt wird.", sourceObjective = "Tötet Or'Kalar und nehmt seinen Kopf.", progress = "Fasst Euch kurz.", completion = "Dieses Schicksal blüht allen, die uns im Weg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26030] = { id = 26030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Strom", description = "In grauer Vorzeit führte Lord Ignaeus von Strom, den sie Trollbann nannten, die erste menschliche Zivilisation von Arathor in den Krieg gegen die Trolle. Seine Klinge hieß Trol'kalar – was in ihrer alten Sprache Trolltöter heißt.\n\nIch war einer der letzten seines Geblüts und hatte die Aufgabe, Trol'kalar zu hüten... eine Aufgabe, bei der ich versagt habe. Aber jetzt werden wir die Klinge für meinen neuen Meister erneut in unseren Besitz bringen.\n\nDas Schwert wird von drei Siegelzeichen beschützt. Der erste befindet sich in den Händen der Verräter des Syndikats, die in den Ruinen von Stromgarde herumlungern. Tötet sie und bringt das Siegelzeichen zu mir.", sourceObjective = "Erhaltet das Siegelzeichen von Strom von den Mitgliedern des Syndikats in Burg Stromgarde.", progress = "Nur die Mitglieder des Syndikats innerhalb Stormgardes werden das Siegelzeichen bei sich haben. Außerhalb der Festung Blut zu vergießen ist Zeitverschwendung.", completion = "Ich habe das Syndikat zu Lebzeiten genauso sehr gehasst, wie ich sie im Tode hasse. Das Siegelzeichen wiederzusehen ist ein kleiner Trost.\n\nAber wir haben noch viel mehr Arbeit vor uns... für Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26031] = { id = 26031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen des Thoradin", description = "Als ich noch lebte, zerbrach ich das Siegelzeichen des Thoradin in fünf Teile, um es zu schützen. Ich gab sie meinen loyalsten Männern. Das schlug ebenfalls fehl, aber mein Nachfolger wird dasselbe getan haben.\n\nDie Verteidiger von Burg Stromgarde tragen die Teile des Siegelzeichens wieder bei sich. Tötet sie und bringt mir die Scherben; ich werde sie zusammensetzen.", sourceObjective = "Erbeutet 5 Siegelzeichenfragmente von Vollstreckern von Stromgarde in Burg Stromgarde.", progress = "Nur mit allen fünf Teilen kann das Siegelzeichen wiederhergestellt werden...", completion = "Thoradin war der Gründer von Arathor. Ich vereine diese Fragmente, so wie er einst die verstreuten Stämme der Menschen vereinte und ihre erste große Nation erschuf.\n\nDoch dieses Gefasel interessiert Euch sicherlich nicht. Vergebt mir. Alte Erinnerungen lassen sich nur schwer begraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26032] = { id = 26032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Arathor", description = "Ich habe dieses Siegelzeichen Leutnant Heldenruf, dem Anführer meiner Kavallerie, anvertraut. Er hätte beinahe sein Leben verloren, als es gestohlen wurde.\n\nDieses Mal wird er wohl weniger Glück haben. Heldenruf patrouilliert zwischen Burg Stromgarde und der Zuflucht. Findet ihn und nehmt ihm noch einmal das Siegelzeichen ab.", sourceObjective = "Nehmt Leutnant Heldenruf das Siegelzeichen von Arathor ab.", progress = "Habt Ihr das Siegelzeichen?", completion = "Heldenruf war mir im Leben treu ergeben. Seinen Tod ertrage ich nur schwer.\n\nDoch das muss ich. Ich bin ein Verlassener. Meine alte Existenz hat keine Bedeutung.\n\nWir haben die Siegelzeichen; Trol'kalar erwartet uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26033] = { id = 26033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "Ich habe das letzte Siegelzeichen... und mit ihm vereine ich die vier zum Siegelzeichen von Trollbann, dem Schlüssel zur Gruft. Wir sind bereit.\n\nTrol'kalar wurde gemeinsam mit den Überresten seines Herrn eingeschlossen. Es liegt in Trollbanns Grabmal in den Katakomben von Burg Stromgarde. Es wird schwer bewacht sein... aber dass ich vor Euch stehe, beweist, dass die Vollstrecker besiegt werden können.\n\nBetretet das Grabmal, bergt Trol'kalar und bringt es her.", sourceObjective = "Bergt Trol'kalar aus Trollbanns Grabmal in Burg Stromgarde.", progress = "Habt Ihr Trol'kalar?", completion = "Trol'kalar, die Klinge meines Vaters... es erscheint mir, als hätte ich sie vor einer Ewigkeit zuletzt gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtzerstörer", description = "Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.\n\nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.\n\nTötet ihn, {name}. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.", sourceObjective = "Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.", completion = "<Krasus hört konzentriert zu, während Ihr von Eurem Kampf gegen Halion berichtet. Seine Augen weiten sich, als Ihr Todesschwinge erwähnt.>\n\nWir schulden Euch großen Dank dafür, dass Ihr die Eindringlinge aus dem Sanktum getrieben habt. Doch die Neuigkeiten über den Zerstörer sind über alle Maße beunruhigend. Es gibt vieles, was ich mit den anderen Mitgliedern des Wyrmruhpakts besprechen muss.\n\nNehmt dies als Zeichen meiner Anerkennung, während Ihr Euch gegen den aufziehenden Sturm wappnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26035] = { id = 26035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Gewicht in Gold", description = "Erzmagier Malin hat mich hierher geschickt, um Reagenzien für ihn zu sammeln. Ich habe mich gefragt, wie ich ihm die Gegenstände besorgen soll, aber nun, da Ihr hier seid, könnte sich dieses Problem erledigt haben.\n\nIch benötige Hauer der Bleichborken und Medizinbeutel der Bleichborken.\n\nWürdet Ihr sie für mich holen? Die Bleichborken leben südöstlich von Arathi.", sourceObjective = "Erbeutet 10 Hauer der Bleichborken und 4 Medizinbeutel der Bleichborken von Trollen der Bleichborken.", progress = "Wie läuft es bislang?", completion = "Nicht schlecht. Da Ihr Euren Kopf anscheinend wirklich zum Denken benutzt, hoffe ich, dass Ihr uns in einer dringenderen Angelegenheit behilflich sein könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26036] = { id = 26036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab gegen Faust", description = "He, {name}. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", sourceObjective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", progress = "Unser Ziel ist der Zauberstab, {name}. Konzentriert Euch vorerst nur darauf.", completion = "Genial, {name}. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26037] = { id = 26037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelanes Verteidigung", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen Euch gegen die Verteidigungsanlagen des Turms einsetzen. Dazu brauchen wir ein paar Edelsteine, an denen der Schamane der Felsfäuste Gefallen gefunden hat. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann.", sourceObjective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten in Burg Stromgarde.", progress = "Da seid Ihr ja wieder, {name}. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, {name}. Nochmals, gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber zu wirken, dann ist alles bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26038] = { id = 26038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm", description = "Hier ist das, wonach Ihr suchen müsst: Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat.\n\nAlle drei liegen in Kisten innerhalb des Turms. Die Kisten solltet Ihr allein problemlos öffnen können, passt nur auf die Oger auf.\n\nHaltet Eure Waffen bereit. Wenn die Oger herausfinden, dass Ihr dort seid und sie bestehlen wollt, dann werden sie nicht zimperlich mit Euch umgehen.\n\nSeid vorsichtig und viel Glück.", sourceObjective = "Findet Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt sie Skuerto in der Zuflucht.", progress = "Wenn Euch das gelingt, wird Malin sehr zufrieden mit Euch sein.", completion = "Malin hat genau die richtige Person um Hilfe gebeten, {name}. Das war tolle Arbeit!\n\nEs wird ihn freuen, dass unsere Mission ein so großartiger Erfolg war.", sourceObjectiveStatus = "unverified-source-field" }
quests[26039] = { id = 26039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Prinzessin", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, {name}, helft mir!", sourceObjective = "Sammelt 12 Körner von Myzrael von Kobolden der Trockenstoppel.", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26040] = { id = 26040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {race}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26041] = { id = 26041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", sourceObjective = "Holt den brennenden Schlüssel, den schäumenden Schlüssel und den donnernden Schlüssel vom Stein der Westlichen Bindung, dem Stein der Östlichen Bindung und dem Stein der Äußeren Bindung.", progress = "Dies ist der Stein der Inneren Bindung. Er ist der stärkste der Bindungssteine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "<Myzrael spricht durch den Stein.>\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger {class}, {name}. Mein Retter!", sourceObjectiveStatus = "unverified-source-field" }
quests[26042] = { id = 26042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hauptstein zerbrechen", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n{name}, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", sourceObjective = "Beschafft die Rute der Ordnung von Fozruk.", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", sourceObjectiveStatus = "unverified-source-field" }
quests[26043] = { id = 26043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl von Oberanführer Krom'gar ist das Betreten des Felskesselsees VERBOTEN!\n\nDie wilde Bestie, die Felskiefer genannt wird, hat den See in eine Todesfalle verwandelt. Solltet Ihr Felskiefer beseitigen, nehmt seinen riesigen Zahn als Trophäe und bringt ihn zur Herrin der Spione Anara. Sie wird Euch belohnen.", sourceObjective = "Tötet Felskiefer und nehmt Euch Felskiefers riesigen Zahn.", progress = "Was wünscht Ihr?", completion = "Ein Beweis für die Macht der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26044] = { id = 26044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Teile?", description = "Ich warte seit Tagen auf Teile für diese Waffen! Ich habe einen meiner besten Sprengenieure und zwei Dutzend Minenarbeiter vor fünf Tagen in die Ausufernden Tiefen geschickt, um die Teile zu besorgen. Als ich drei Tage später noch nichts von ihnen gehört hatte, begann ich mir Sorgen zu machen. Der Oberanführer schickte zwei seiner besten Orcs hinterher. Seitdem haben wir nichts gehört...\n\nBegebt Euch in die Ausufernden Tiefen, unmittelbar unter dieser Festung, und findet heraus, was los ist! Ich brauche die Teile!", sourceObjective = "Sprecht mit Unteroffizier Dontrag in den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Äh... Na ja, das ist ganz einfach... IN DIESER HÖHLE WIMMELT ES VON SEELENLOSEN MORDMASCHINEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[26045] = { id = 26045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Teile sind schon hier...", description = "Mein Dilemma sieht so aus: Ich habe zwei Möglichkeiten. Entweder lasse ich mich wie alle anderen hier unten umbringen oder ich werde in der Feste Krom'gar umgebracht, wenn Krom'gar erfährt, dass wir die Mine verloren haben. Ich wähle die dritte Möglichkeit: nichts tun. Klappt bisher ganz gut.\n\nIhr braucht Teile? In der Mine liegt eine Menge Schrott herum. Ihr müsst ihn nur holen.\n\nViel Glück! Wenn Ihr diese Teile holt, können wir uns vielleicht wieder in der Feste Krom'gar blicken lassen.", sourceObjective = "Sammelt 10 Ersatzteile.", progress = "Wie läuft die Jagd?", completion = "Ich fasse es nicht! Ihr habt die Teile bekommen und seid nicht gestorben. Wieso seid Ihr nur Unteroffizier?", sourceObjectiveStatus = "unverified-source-field" }
quests[26046] = { id = 26046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was immer wir tun...", description = "Dontrag kann das besser erklären als ich. Was auch immer wir tun, es ist das Falsche. Wir können hier unten nichts tun wegen all der Dinge, die uns umbringen wollen und können nicht zur Basis zurückkehren wegen all der Dinge, die uns umbringen wollen - verstanden?\n\nVielleicht können wir dieses Problem ja gemeinsam lösen. Beseitigt Ihr doch schon mal ein paar dieser Elementare, die anscheinend alles in der Mine umgebracht haben, einverstanden?", sourceObjective = "Tötet 12 tobende Erdelementare.", completion = "Holt die Teile, tötet die Elementare und rettet die Peons... Wenn wir das hinkriegen, ist uns eine Beförderung sicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[26047] = { id = 26047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deshalb nennt man sie Peons...", description = "Die beiden sind NUTZLOS! Als sie eintrafen, dachte ich, wir wären gerettet. Aber nein! Stattdessen warfen Dontrag und Utvoch einen Blick in die Mine und dachten sich einen idiotischen Plan aus, der vor allem aus Herumstehen besteht... wahrscheinlich, bis wir alle tot sind. \n\nIhr seht nicht ganz so nutzlos aus. Wollt Ihr uns helfen, <Freund/Freundin>? In den Ausufernden Tiefen verstecken sich Dutzende von Peons, die nur noch Angst in der Birne haben. Findet sie und holt sie raus!", sourceObjective = "Rettet 10 verängstigte Peons.", progress = "Habt Ihr meine Peons gefunden?", completion = "Ich wusste es! Ihr seid ein Held! Wenn ich etwas zu sagen hätte, würdet Ihr zum Legionär befördert!", sourceObjectiveStatus = "unverified-source-field" }
quests[26048] = { id = 26048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile hier herauf!", description = "Puh, das war hart. Ich dachte, wir würden es nicht schaffen, {name}. Am besten bringen wir diese Teile zurück zu Obersprengenieurin Bombgutz. Ich glaube, ich höre draußen schon das Summen der Gnomflugmaschinen. Wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt die Kiste mit Ersatzteilen zu Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", progress = "Habt Ihr meine Teile?", completion = "Gerade noch rechtzeitig! Die Flugmaschinen sammeln sich bereits. Der Angriff steht unmittelbar bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[26049] = { id = 26049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entfesselte Prinzessin", description = "Myzrael ist keine unschuldige Prinzessin. Sie ist unglaublich gefährlich. Die Riesen hatten sie aus gutem Grund dort unten angekettet. Man hat Euch leider betrogen.\n\nGerrig sagt, dass Ihr sie bei den Splittern von Myzrael, dort, wo Ihr zuerst mit ihr gesprochen habt, beschwören müsst. Besiegt sie und nehmt Euch ihre geisterhaften Fesseln. Bindet sie damit an die Splitter.\n\nIhr werdet diese Schriftrolle brauchen. Geht sorgsam mit ihr um; ich habe ein paar Zähne riskiert, um sie zu bekommen. Viel Glück, {name}.", sourceObjective = "Beschwört und besiegt Myzrael an den Splittern von Myzrael.", progress = "Die Splitter von Myzrael sind nun seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[26050] = { id = 26050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtbrille", description = "Als frisch gebackene Schwarzmeerräuber ist es unsere Aufgabe, dem ehrenwerten O'Breen bei der Suche nach dem verlorenen Elfenschatz zu helfen.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfsmittel im dunklen Wasser zu finden. Der Doktor hat für diesen Fall eine Brille konstruiert. Die Brille muss mit der Energie aus dem verzauberten Stein in der Höhle auf dem Hügel aufgeladen werden.\n\nDoch die Höhle ist verflucht! Man wird uns angreifen, wenn wir näher kommen. Verteidigt mich, dann kann ich die Energie aus dem Stein in die Brille übertragen.", sourceObjective = "Begleitet Professor Prasseltrop zur Höhle und zurück.", completion = "Die Brille funktioniert nun perfekt! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26051] = { id = 26051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, {name}, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", sourceObjective = "Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, {name}. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26052] = { id = 26052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Wank", description = "Lassen wir Kapitän O'Breen nicht warten. Er wird die Edelsteine selbst sehen wollen. Deshalb sind wir schließlich hier!\n\nUnd nach ein paar Wochen in der Gesellschaft dieser Piraten haben der Professor und ich erkannt, dass es äußerst gesundheitsschädlich ist, sich mit ihren Schätzen erwischen zu lassen.\n\nHier, {name}, bringt sie zu O'Breen.", sourceObjective = "Bringt die Elfenedelsteine zu Kapitän O'Breen in der Faldirbucht im Arathihochland.", progress = "Ahoi, {class}. Was führt Euch auf die Brücke?", completion = "Dann haben sich die kleinen Gnome tatsächlich als nützlich erwiesen? Ich wusste doch, dass wir die Fersenbeißer nicht grundlos mitschleppen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26053] = { id = 26053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Hochlands", description = "Wir werden keine Bedrohung übersehen. Um dieses Land zu sichern und der Dunklen Fürstin zu unterwerfen, müssen wir alles, was auf ihm lebt, herausreißen, Stück für Stück, Meter für Meter.\n\nIm Nordosten, weniger als einen Steinwurf von diesem Lager entfernt, befindet sich ein Ogerhügel. Die Oger der Felsfäuste, die dort leben, müssen ausgelöscht werden, {class}.\n\nSie stehen uns im Weg. Zögert nicht und seid nicht gnädig.", sourceObjective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste.", completion = "Hervorragend. Der Marsch der Verlassenen geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[26055] = { id = 26055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertrunkene Trauer", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", sourceObjective = "Kapitän Stahlmagen in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberinnen der Säbelflossen tötet.", completion = "Ihr habt da draußen gute Arbeit geleistet, {name}.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26056] = { id = 26056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26057] = { id = 26057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26058] = { id = 26058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Feste Krom'gar", description = "Wir haben keine Zeit mehr. Sie kommen! Übernehmt die Kontrolle über eine schwere Kanone und holt die Gnome vom Himmel! Die Bombe wird explodieren, wenn sie zu oft getroffen wird, und wir mit ihr!\n\nVerteidigt die Basis, {name}! Ihr seid unsere einzige Hoffnung!\n\nMeldet Euch bei Oberanführer Krom'gar, sollten wir das wider Erwarten überleben.", sourceObjective = "Zerstört 15 gnomische Flugmaschinen oder Gnomenbomber und 25 Gnomenschwadronskommandanten.", progress = "Unsere Feinde umzingeln uns!", completion = "Ich habe noch nie eine so mutige Tat gesehen. Ihr habt die Basis gerettet, Unteroffizier - oder sollte ich besser Legionär sagen! Lok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26059] = { id = 26059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen und Ohren: Malaka'jin", description = "Ehrenwacht ist gefallen. Der Griff, in dem die Horde das Brachland hielt, wurde aufgesprengt, ebenso wie das Land. Nun erhalte ich Berichte, in denen es heißt, ein gemeinsamer Angriff der Allianz und der Grimmtotem würde Malaka'jin bedrohen. Wenn Malaka'jin fällt, fällt auch das halbe Steinkrallengebirge!\n\nIhr habt Euch als ein fähiger Soldat der Horde erwiesen. Wollt Ihr meine Augen und Ohren in Malaka'jin sein? Hexendoktor Jin'Zil erwartet Euch.\n\nMalaka'jin befindet sich weit im Süden.", sourceObjective = "Meldet Euch bei Hexendoktor Jin'Zil in Malaka'jin im Steinkrallengebirge", completion = "Wie ich sehe, schickt Krom'gar den Besten!\n\nGut, wir haben viel zu tun. Die dreckige Allianz hat ein Abkommen mit den Grimmtotem unterzeichnet. Jetzt müssen wir die Angriffe beider Streitkräfte abwehren.\n\nWir haben nicht genügend Soldaten im Hochwipfeltal und können es nicht mehr lange gegen die konzentrierten Angriffe unserer Feinde verteidigen. Wir haben nur noch eine Hoffnung: VOODOO!", sourceObjectiveStatus = "unverified-source-field" }
quests[26060] = { id = 26060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Stürmerherz", description = "Mit Voodoo könnte es unseren Truppen gelingen, den Angriff der Grimmtotem zurückzuschlagen. Allerdings brauche ich verschiedene Zutaten, um diese schwarze Magie zu wirken.\n\nDie erste Zutat auf meiner Liste ist das Herz eines Klippenstürmers. Die Bestien sind fast ausgerottet, aber in dieser Gegend gibt es noch ein paar. Findet eine und erbeutet ihr klopfendes Herz!", sourceObjective = "Besorgt ein Klippenstürmerherz.", progress = "Ich brauche das Klippenstürmerherz.", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26061] = { id = 26061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Widderhörner", description = "Um den Voodoo zu wirken, brauche ich besondere Reagenzien. Bringt mir Hörner der Steinkrallenwidder in dieser Gegend, {name}! Ohne die Hörner sind wir erledigt!", sourceObjective = "Besorgt 6 Hörner eines Steinkrallenwidders.", progress = "Ich brauche Hörner von Steinkrallenwiddern!", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26062] = { id = 26062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Resonitkristall", description = "Die letzte Zutat für das Voodooritual ist eine spezielle Kristallart namens Resonit. Man findet sie nur in den Steinschlaghöhlen westlich von hier. Passt auf die Kobolde auf! Sie beschützen das Resonit mit ihrem Leben!", sourceObjective = "Besorgt 8 Resonitkristalle.", progress = "Ich brauche die Resonitkristalle!", completion = "Endlich! Nun kann ich das Amulett mit der Voodooverzauberung erschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26063] = { id = 26063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin und ihr Hofstaat", description = "<Scholli grunzt.>\n\nHrmph.\n\nDinge brechen auseinander. Scholli unglücklich. Jetzt Schollis Gefährtin umgebracht von Spinnen in Weberkuhle. Scholli will Rache!\n\nHelft Scholli? Tötet Königin Silith und ihre kleinen Spinnlinge? Für Scholli? Für Schollis Gefährtin!\n\nWeberpass ist im Nordwesten, den Weg hoch. Geht!", sourceObjective = "Tötet Königin Silith und 10 beliebige Spinnen in der Weberkuhle.", progress = "Habt Ihr Silith für Scholli getötet?", completion = "Scholli immer noch nicht sehr glücklich, aber Scholli wird Euch für Tat belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26064] = { id = 26064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Kampf auf leeren Magen", description = "Die Truppen sind hungrig, {name}. Seit unsere Nachschublinien abgeschnitten wurden, gehen uns die Vorräte aus. Ich kann den Soldaten ein Festmahl zubereiten, wenn Ihr mir einige Zutaten besorgt.\n\nBegebt Euch in die Wälder westlich von hier und sucht nach Nestern der Kalimdoradler. Stehlt die Eier aus den Nestern und bringt sie mir.", sourceObjective = "Beschafft 8 Eier des Kalimdoradlers.", progress = "Ich brauche Eier!", completion = "Danke, {name}. Diese Eier reichen für eine Woche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26065] = { id = 26065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Willi", description = "Diese Tentakelschrecken haben das arme Tier eingefangen. Bitte, {name}, könnt Ihr es nicht retten, indem Ihr diese Abscheulichkeiten tötet?\n\nWürdet Ihr Willi seine Freiheit zurückgeben?\n\nHier, nehmt mein Totem und stellt es in der Nähe der Tentakel auf. Die Kälte, die es verströmt, bringt diese Monster zum Schrumpfen, sodass Ihr sie einfach besiegen könnt.", sourceObjective = "Tötet alle Tentakelschrecken, um Willi zu befreien.", completion = "Danke, {name}.\n\nDiese alptraumhaften Gestalten aus der Tiefe geben mir zu denken. Ich fürchte, dass unsere Anstrengungen vollkommen umsonst sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26066] = { id = 26066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung...", description = "Anscheinend haben wir fast keine großen, dummen Orcs mehr, die wir dem Feind entgegenschicken können. Das ist ein Problem. Zum Glück habe ich möglicherweise eine Lösung.\n\nNehmt diese Peitsche und geht nach Westen zur Steinschlaghöhle. In der Höhle werdet ihr ein schmutziges Koboldnest finden. Bändigt die Bestien mit meiner Peitsche. Wenn sie erst einmal gebändigt sind, werden sie tun, was wir wollen.\n\nKehrt zurück, wenn ihr eine anständig große Koboldarmee zusammen habt.", sourceObjective = "Bändigt 6 Steinschlagkobolde mit der Peitsche von Unterwerfer Devo.", completion = "In einer Krise wie dieser, könnte eine verzweifelte Tat uns den Sieg bringen. Vielleicht gewinnen wir, wenn wir einen Schwarm Kobolde auf den Feind hetzen.", sourceObjectiveStatus = "unverified-source-field" }
